window.CODIGO_JAVA = window.CODIGO_JAVA || {};
window.CODIGO_JAVA["pedidos-ventas-ms"] = {"src/main/java/com/mx/josesaid/develop/pedidos/PedidosVentasApplication.java": "package com.mx.josesaid.develop.pedidos;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de pedidos-ventas-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class PedidosVentasApplication {\n\n    /** Arranca la aplicación Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(PedidosVentasApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/api/ManejadorErrores.java": "package com.mx.josesaid.develop.pedidos.api;\n\nimport com.mx.josesaid.develop.pedidos.domain.ConflictoException;\nimport com.mx.josesaid.develop.pedidos.domain.CotizacionVencidaException;\nimport com.mx.josesaid.develop.pedidos.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.pedidos.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.pedidos.domain.SolicitudInvalidaException;\nimport java.net.URI;\nimport org.springframework.dao.OptimisticLockingFailureException;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/** Convierte excepciones en respuestas RFC 9457 (application/problem+json). */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    /** Convierte una regla de negocio incumplida en un problema HTTP. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ResponseEntity<ProblemDetail> reglaDeNegocio(ReglaDeNegocioException e) {\n        return respuesta(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", e.getMessage());\n    }\n\n    /** Convierte un recurso inexistente en un problema HTTP. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ResponseEntity<ProblemDetail> noEncontrado(RecursoNoEncontradoException e) {\n        return respuesta(HttpStatus.NOT_FOUND, \"recurso-no-encontrado\", e.getMessage());\n    }\n\n    /** Convierte un conflicto de estado, por ejemplo confirmar un pedido que ya no está en borrador, en un problema HTTP. */\n    @ExceptionHandler(ConflictoException.class)\n    ResponseEntity<ProblemDetail> conflicto(ConflictoException e) {\n        return respuesta(HttpStatus.CONFLICT, \"conflicto-de-estado\", e.getMessage());\n    }\n\n    /** Convierte una solicitud inválida en un problema HTTP. */\n    @ExceptionHandler(SolicitudInvalidaException.class)\n    ResponseEntity<ProblemDetail> solicitudInvalida(SolicitudInvalidaException e) {\n        return respuesta(HttpStatus.BAD_REQUEST, \"solicitud-invalida\", e.getMessage());\n    }\n\n    /** Responde 410 cuando la cotización ya venció. La cotización no se reactiva: hay que crear una nueva. */\n    @ExceptionHandler(CotizacionVencidaException.class)\n    ResponseEntity<ProblemDetail> cotizacionVencida(CotizacionVencidaException e) {\n        return respuesta(HttpStatus.GONE, \"cotizacion-vencida\", e.getMessage());\n    }\n\n    /** Dos usuarios modificaron el mismo registro: el segundo recibe 409 y debe volver a leer. */\n    @ExceptionHandler(OptimisticLockingFailureException.class)\n    ResponseEntity<ProblemDetail> concurrencia(OptimisticLockingFailureException e) {\n        return respuesta(HttpStatus.CONFLICT, \"conflicto-concurrencia\",\n                \"El registro cambió mientras se procesaba. Vuelva a leerlo e intente de nuevo.\");\n    }\n\n    /** Responde cuando un servicio externo, como clientes-ms, no está disponible. */\n    @ExceptionHandler(com.mx.josesaid.develop.pedidos.domain.ServicioNoDisponibleException.class)\n    ResponseEntity<ProblemDetail> servicioNoDisponible(com.mx.josesaid.develop.pedidos.domain.ServicioNoDisponibleException e) {\n        return respuesta(HttpStatus.SERVICE_UNAVAILABLE, \"servicio-no-disponible\", e.getMessage());\n    }\n\n    /** Construye la respuesta de error con su estatus, código y detalle. */\n    private static ResponseEntity<ProblemDetail> respuesta(HttpStatus estado, String slug, String detalle) {\n        ProblemDetail problema = ProblemDetail.forStatusAndDetail(estado, detalle);\n        problema.setTitle(estado.getReasonPhrase());\n        problema.setType(URI.create(\"urn:josesaid:pedidos-ventas:error:\" + slug));\n        return ResponseEntity.status(estado).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(problema);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/api/PedidosControlador.java": "package com.mx.josesaid.develop.pedidos.api;\n\nimport com.mx.josesaid.develop.pedidos.application.PedidosService;\nimport com.mx.josesaid.develop.pedidos.application.PedidosService.LineaComando;\nimport com.mx.josesaid.develop.pedidos.domain.Canal;\nimport com.mx.josesaid.develop.pedidos.domain.Cotizacion;\nimport com.mx.josesaid.develop.pedidos.domain.EstatusCotizacion;\nimport com.mx.josesaid.develop.pedidos.domain.EstatusPedido;\nimport com.mx.josesaid.develop.pedidos.domain.Linea;\nimport com.mx.josesaid.develop.pedidos.domain.MotivoCancelacion;\nimport com.mx.josesaid.develop.pedidos.domain.Monedas;\nimport com.mx.josesaid.develop.pedidos.domain.Pedido;\nimport com.mx.josesaid.develop.pedidos.domain.TasaIva;\nimport com.mx.josesaid.develop.pedidos.infrastructure.idempotencia.Idempotencia;\nimport com.mx.josesaid.develop.pedidos.domain.Totales;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.DecimalMin;\nimport jakarta.validation.constraints.Min;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotEmpty;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Size;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.format.annotation.DateTimeFormat;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.PutMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestHeader;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RestController;\n\n/**\n * API de ventas. Autorización por rol: VENTAS opera cotizaciones y pedidos, ALMACEN entrega,\n * DIRECCION y FINANZAS consultan métricas. Los errores salen como RFC 9457 desde ManejadorErrores.\n */\n@RestController\n@RequestMapping(\"/v1\")\npublic class PedidosControlador {\n\n    private final PedidosService servicio;\n    private final Idempotencia idempotencia;\n\n    /** Recibe el servicio de ventas y el control de idempotencia. */\n    public PedidosControlador(PedidosService servicio, Idempotencia idempotencia) {\n        this.servicio = servicio;\n        this.idempotencia = idempotencia;\n    }\n\n    // ---- Cotizaciones ----\n\n    /** Crea una cotización en borrador para un cliente activo. */\n    @PostMapping(\"/cotizaciones\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public ResponseEntity<CotizacionRespuesta> crearCotizacion(@Valid @RequestBody CrearCotizacionPeticion p) {\n        Cotizacion c = servicio.crearCotizacion(p.clienteId(), p.canal(), p.moneda(), p.tasaIva(),\n                p.vigenteHasta(), aComandos(p.lineas()));\n        return ResponseEntity.status(HttpStatus.CREATED).body(CotizacionRespuesta.de(c));\n    }\n\n    /** Devuelve una cotización por id. */\n    @GetMapping(\"/cotizaciones/{id}\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION','FINANZAS')\")\n    public CotizacionRespuesta obtenerCotizacion(@PathVariable UUID id) {\n        return CotizacionRespuesta.de(servicio.obtenerCotizacion(id));\n    }\n\n    /** Envía la cotización al cliente: pasa de borrador a enviada. */\n    @PostMapping(\"/cotizaciones/{id}/envio\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public CotizacionRespuesta enviarCotizacion(@PathVariable UUID id) {\n        return CotizacionRespuesta.de(servicio.enviarCotizacion(id));\n    }\n\n    /** Acepta la cotización. Si ya venció, responde 410 y la marca como vencida. */\n    @PostMapping(\"/cotizaciones/{id}/aceptacion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public CotizacionRespuesta aceptarCotizacion(@PathVariable UUID id) {\n        return CotizacionRespuesta.de(servicio.aceptarCotizacion(id));\n    }\n\n    /** Convierte una cotización aceptada en un pedido en borrador. Solo puede hacerse una vez. */\n    @PostMapping(\"/cotizaciones/{id}/pedido\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public ResponseEntity<PedidoRespuesta> convertirEnPedido(@PathVariable UUID id) {\n        Pedido p = servicio.convertirEnPedido(id);\n        return ResponseEntity.status(HttpStatus.CREATED).body(PedidoRespuesta.de(p));\n    }\n\n    // ---- Pedidos ----\n\n    /** Crea un pedido en borrador directamente, sin cotización. Acepta Idempotency-Key. */\n    @PostMapping(\"/pedidos\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public ResponseEntity<?> crearPedido(@RequestHeader(value = Idempotencia.CABECERA, required = false) String clave,\n                                         @Valid @RequestBody CrearPedidoPeticion p) {\n        return idempotencia.ejecutar(clave, \"POST /v1/pedidos\", p, HttpStatus.CREATED,\n                () -> PedidoRespuesta.de(servicio.crearPedido(p.clienteId(), p.canal(), p.moneda(), p.tasaIva(), aComandos(p.lineas()))));\n    }\n\n    /** Busca pedidos por cliente, estatus o canal. Todos los filtros son opcionales. */\n    @GetMapping(\"/pedidos\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION','FINANZAS')\")\n    public List<PedidoRespuesta> buscarPedidos(@RequestParam(required = false) UUID clienteId,\n                                               @RequestParam(required = false) EstatusPedido estatus,\n                                               @RequestParam(required = false) Canal canal) {\n        return servicio.buscarPedidos(clienteId, estatus, canal).stream().map(PedidoRespuesta::de).toList();\n    }\n\n    /** Devuelve un pedido por id. */\n    @GetMapping(\"/pedidos/{id}\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION','FINANZAS','ALMACEN')\")\n    public PedidoRespuesta obtenerPedido(@PathVariable UUID id) {\n        return PedidoRespuesta.de(servicio.obtenerPedido(id));\n    }\n\n    /** Reemplaza las líneas de un pedido. Solo se permite mientras está en borrador. */\n    @PutMapping(\"/pedidos/{id}/lineas\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public PedidoRespuesta reemplazarLineas(@PathVariable UUID id, @Valid @RequestBody LineasPeticion p) {\n        return PedidoRespuesta.de(servicio.reemplazarLineas(id, aComandos(p.lineas())));\n    }\n\n    /** Confirma el pedido y publica el evento para que inventario reserve las piezas. */\n    @PostMapping(\"/pedidos/{id}/confirmacion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public PedidoRespuesta confirmarPedido(@PathVariable UUID id) {\n        return PedidoRespuesta.de(servicio.confirmarPedido(id));\n    }\n\n    /** Marca el pedido como entregado y publica el evento para que inventario descuente las piezas. */\n    @PostMapping(\"/pedidos/{id}/entrega\")\n    @PreAuthorize(\"hasAnyRole('ALMACEN','DIRECCION')\")\n    public PedidoRespuesta entregarPedido(@PathVariable UUID id) {\n        return PedidoRespuesta.de(servicio.entregarPedido(id));\n    }\n\n    /** Cancela un pedido en borrador o confirmado. Requiere el motivo. */\n    @PostMapping(\"/pedidos/{id}/cancelacion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public PedidoRespuesta cancelarPedido(@PathVariable UUID id, @Valid @RequestBody CancelacionPeticion p) {\n        return PedidoRespuesta.de(servicio.cancelarPedido(id, p.motivo()));\n    }\n\n    /** Registra la devolución total de un pedido entregado. Lo pasa a cancelado con motivo de devolución. */\n    @PostMapping(\"/pedidos/{id}/devolucion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','DIRECCION')\")\n    public PedidoRespuesta devolverPedido(@PathVariable UUID id) {\n        return PedidoRespuesta.de(servicio.devolverPedido(id));\n    }\n\n    // ---- Métricas y catálogos ----\n\n    /** Devuelve el resumen de ventas netas del mes indicado, por moneda. */\n    @GetMapping(\"/metricas/ventas\")\n    @PreAuthorize(\"hasAnyRole('DIRECCION','FINANZAS')\")\n    public ResumenVentasRespuesta resumenVentas(\n            @RequestParam @DateTimeFormat(pattern = \"yyyy-MM\") YearMonth mes) {\n        PedidosService.ResumenVentas r = servicio.resumenVentas(mes);\n        return new ResumenVentasRespuesta(r.mes().toString(), r.pedidos(), r.ventasPorMoneda());\n    }\n\n    /** Catálogo de tasas de IVA disponibles. */\n    @GetMapping(\"/catalogos/tasas-iva\")\n    @PreAuthorize(\"isAuthenticated()\")\n    public List<Map<String, Object>> tasasIva() {\n        return Arrays.stream(TasaIva.values())\n                .map(t -> Map.<String, Object>of(\"codigo\", t.name(), \"tasa\", t.valor()))\n                .toList();\n    }\n\n    /** Catálogo de monedas con sus decimales. */\n    @GetMapping(\"/catalogos/monedas\")\n    @PreAuthorize(\"isAuthenticated()\")\n    public Map<String, Integer> monedas() {\n        return Monedas.catalogo();\n    }\n\n    // ---- Mapeo de peticiones ----\n\n    /** Convierte las líneas recibidas en la API en comandos de la capa de aplicación. */\n    private static List<LineaComando> aComandos(List<LineaPeticion> lineas) {\n        if (lineas == null) {\n            return List.of();\n        }\n        return lineas.stream()\n                .map(l -> new LineaComando(l.productoId(), l.descripcion(), l.cantidad(), l.precioUnitario()))\n                .toList();\n    }\n\n    // ---- Peticiones ----\n\n    /**\n     * Línea de una cotización o pedido: producto, cantidad y precio.\n     *\n     * @param productoId identificador del producto, de tipo {@code UUID}.\n     * @param descripcion descripcion, de tipo {@code String}.\n     * @param cantidad cantidad solicitada o registrada, de tipo {@code int}.\n     * @param precioUnitario precio unitario, de tipo {@code BigDecimal}.\n     */\n    public record LineaPeticion(\n            @NotNull UUID productoId,\n            @Size(max = 200) String descripcion,\n            @Min(1) int cantidad,\n            @NotNull @DecimalMin(\"0.00\") BigDecimal precioUnitario) {\n    }\n\n    /**\n     * Datos para crear una cotización.\n     *\n     * @param clienteId identificador del cliente, de tipo {@code UUID}.\n     * @param canal canal, de tipo {@code Canal}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param tasaIva tasa de IVA aplicable, de tipo {@code TasaIva}.\n     * @param vigenteHasta vigente hasta, de tipo {@code LocalDate}.\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaPeticion>}.\n     */\n    public record CrearCotizacionPeticion(\n            @NotNull UUID clienteId,\n            @NotNull Canal canal,\n            @NotBlank String moneda,\n            @NotNull TasaIva tasaIva,\n            @NotNull LocalDate vigenteHasta,\n            @NotEmpty @Size(max = 100) List<@Valid LineaPeticion> lineas) {\n    }\n\n    /**\n     * Datos para crear un pedido directo.\n     *\n     * @param clienteId identificador del cliente, de tipo {@code UUID}.\n     * @param canal canal, de tipo {@code Canal}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param tasaIva tasa de IVA aplicable, de tipo {@code TasaIva}.\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaPeticion>}.\n     */\n    public record CrearPedidoPeticion(\n            @NotNull UUID clienteId,\n            @NotNull Canal canal,\n            @NotBlank String moneda,\n            @NotNull TasaIva tasaIva,\n            @NotEmpty @Size(max = 100) List<@Valid LineaPeticion> lineas) {\n    }\n\n    /**\n     * Lista de líneas para reemplazar las del pedido.\n     *\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaPeticion>}.\n     */\n    public record LineasPeticion(@NotNull @Size(max = 100) List<@Valid LineaPeticion> lineas) {\n    }\n\n    /**\n     * Motivo de la cancelación.\n     *\n     * @param motivo motivo del registro o de la acción, de tipo {@code MotivoCancelacion}.\n     */\n    public record CancelacionPeticion(@NotNull MotivoCancelacion motivo) {\n    }\n\n    // ---- Respuestas ----\n\n    /**\n     * Respuesta de una línea.\n     *\n     * @param productoId identificador del producto, de tipo {@code UUID}.\n     * @param descripcion descripcion, de tipo {@code String}.\n     * @param cantidad cantidad solicitada o registrada, de tipo {@code int}.\n     * @param precioUnitario precio unitario, de tipo {@code BigDecimal}.\n     * @param subtotal subtotal antes de impuestos, de tipo {@code BigDecimal}.\n     */\n    public record LineaRespuesta(UUID productoId, String descripcion, int cantidad,\n                                 BigDecimal precioUnitario, BigDecimal subtotal) {\n        /** Convierte las líneas del dominio en su respuesta. */\n        static List<LineaRespuesta> de(List<Linea> lineas) {\n            return lineas.stream()\n                    .map(l -> new LineaRespuesta(l.getProductoId(), l.getDescripcion(), l.getCantidad(),\n                            l.getPrecioUnitario(), l.subtotal()))\n                    .toList();\n        }\n    }\n\n    /**\n     * Respuesta de una cotización.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param clienteId identificador del cliente, de tipo {@code UUID}.\n     * @param canal canal, de tipo {@code Canal}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param tasaIva tasa de IVA aplicable, de tipo {@code TasaIva}.\n     * @param vigenteHasta vigente hasta, de tipo {@code LocalDate}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusCotizacion}.\n     * @param pedidoId identificador del pedido, de tipo {@code UUID}.\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaRespuesta>}.\n     * @param totales totales, de tipo {@code Totales}.\n     */\n    public record CotizacionRespuesta(UUID id, UUID clienteId, Canal canal, String moneda, TasaIva tasaIva,\n                                      LocalDate vigenteHasta, EstatusCotizacion estatus, UUID pedidoId,\n                                      List<LineaRespuesta> lineas, Totales totales) {\n        /** Convierte una cotización en su respuesta. */\n        static CotizacionRespuesta de(Cotizacion c) {\n            return new CotizacionRespuesta(c.getId(), c.getClienteId(), c.getCanal(), c.getMoneda(), c.getTasa(),\n                    c.getVigenteHasta(), c.getEstatus(), c.getPedidoId(),\n                    LineaRespuesta.de(c.getLineas()), c.totales());\n        }\n    }\n\n    /**\n     * Respuesta de un pedido.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param clienteId identificador del cliente, de tipo {@code UUID}.\n     * @param cotizacionId identificador del cotizacion, de tipo {@code UUID}.\n     * @param canal canal, de tipo {@code Canal}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param tasaIva tasa de IVA aplicable, de tipo {@code TasaIva}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusPedido}.\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaRespuesta>}.\n     * @param totales totales, de tipo {@code Totales}.\n     * @param fechaConfirmacion fecha confirmacion, de tipo {@code Instant}.\n     * @param fechaEntrega fecha entrega, de tipo {@code Instant}.\n     * @param motivoCancelacion motivo cancelacion, de tipo {@code MotivoCancelacion}.\n     */\n    public record PedidoRespuesta(UUID id, UUID clienteId, UUID cotizacionId, Canal canal, String moneda,\n                                  TasaIva tasaIva, EstatusPedido estatus, List<LineaRespuesta> lineas,\n                                  Totales totales, Instant fechaConfirmacion, Instant fechaEntrega,\n                                  MotivoCancelacion motivoCancelacion) {\n        /** Convierte un pedido en su respuesta. */\n        static PedidoRespuesta de(Pedido p) {\n            return new PedidoRespuesta(p.getId(), p.getClienteId(), p.getCotizacionId(), p.getCanal(),\n                    p.getMoneda(), p.getTasa(), p.getEstatus(), LineaRespuesta.de(p.getLineas()),\n                    p.totales(), p.getFechaConfirmacion(), p.getFechaEntrega(), p.getMotivoCancelacion());\n        }\n    }\n\n    /**\n     * Resumen de ventas de un mes.\n     *\n     * @param mes mes, de tipo {@code String}.\n     * @param pedidos pedidos, de tipo {@code long}.\n     * @param ventasPorMoneda ventas por moneda, de tipo {@code Map<String, BigDecimal>}.\n     */\n    public record ResumenVentasRespuesta(String mes, long pedidos, Map<String, BigDecimal> ventasPorMoneda) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/application/EventoDominio.java": "package com.mx.josesaid.develop.pedidos.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio. Se guarda en el outbox y luego se envía a Kafka.\n *\n * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/application/PedidosService.java": "package com.mx.josesaid.develop.pedidos.application;\n\nimport com.mx.josesaid.develop.pedidos.domain.Canal;\nimport com.mx.josesaid.develop.pedidos.domain.Cotizacion;\nimport com.mx.josesaid.develop.pedidos.domain.CotizacionRepositorio;\nimport com.mx.josesaid.develop.pedidos.domain.CotizacionVencidaException;\nimport com.mx.josesaid.develop.pedidos.domain.EstatusPedido;\nimport com.mx.josesaid.develop.pedidos.domain.Linea;\nimport com.mx.josesaid.develop.pedidos.domain.MotivoCancelacion;\nimport com.mx.josesaid.develop.pedidos.domain.Monedas;\nimport com.mx.josesaid.develop.pedidos.domain.Pedido;\nimport com.mx.josesaid.develop.pedidos.domain.PedidoRepositorio;\nimport com.mx.josesaid.develop.pedidos.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.pedidos.domain.TasaIva;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneOffset;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.TreeMap;\nimport java.util.UUID;\nimport java.util.stream.Collectors;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Casos de uso de ventas: cotizaciones, pedidos, devoluciones y métricas. */\n@Service\npublic class PedidosService {\n\n    private final CotizacionRepositorio cotizaciones;\n    private final PedidoRepositorio pedidos;\n    private final PublicadorEventos eventos;\n    private final Clock reloj;\n    private final ValidadorCliente clientes;\n\n    /** Recibe los repositorios, el publicador de eventos, el reloj y el validador de clientes. */\n    public PedidosService(CotizacionRepositorio cotizaciones, PedidoRepositorio pedidos,\n                          PublicadorEventos eventos, Clock reloj,\n                          ValidadorCliente clientes) {\n        this.cotizaciones = cotizaciones;\n        this.pedidos = pedidos;\n        this.eventos = eventos;\n        this.reloj = reloj;\n        this.clientes = clientes;\n    }\n\n    /**\n     * Línea tal como llega de la API, antes de validarse en el dominio.\n     *\n     * @param productoId identificador del producto, de tipo {@code UUID}.\n     * @param descripcion descripcion, de tipo {@code String}.\n     * @param cantidad cantidad solicitada o registrada, de tipo {@code int}.\n     * @param precioUnitario precio unitario, de tipo {@code BigDecimal}.\n     */\n    public record LineaComando(UUID productoId, String descripcion, int cantidad, BigDecimal precioUnitario) {\n    }\n\n    /**\n     * Ventas netas de un mes: pedidos confirmados o entregados, sin los cancelados ni devueltos.\n     *\n     * @param mes mes, de tipo {@code YearMonth}.\n     * @param pedidos pedidos, de tipo {@code long}.\n     * @param ventasPorMoneda ventas por moneda, de tipo {@code Map<String, BigDecimal>}.\n     */\n    public record ResumenVentas(YearMonth mes, long pedidos, Map<String, BigDecimal> ventasPorMoneda) {\n    }\n\n    /** Crea una cotización en borrador. Falla si el cliente no está activo. */\n    @Transactional\n    public Cotizacion crearCotizacion(UUID clienteId, Canal canal, String moneda, TasaIva tasa,\n                                      LocalDate vigenteHasta, List<LineaComando> lineas) {\n        clientes.exigirActivo(clienteId);\n        return cotizaciones.guardar(Cotizacion.crear(clienteId, canal, moneda, tasa, vigenteHasta, aLineas(lineas)));\n    }\n\n    /** Envía la cotización al cliente. */\n    @Transactional\n    public Cotizacion enviarCotizacion(UUID id) {\n        Cotizacion c = cargarCotizacion(id);\n        c.enviar();\n        return cotizaciones.guardar(c);\n    }\n\n    /**\n     * Si la cotización venció, se guarda como VENCIDA y se responde 410. Por eso no se revierte la transacción.\n     */\n    @Transactional(noRollbackFor = CotizacionVencidaException.class)\n    public Cotizacion aceptarCotizacion(UUID id) {\n        Cotizacion c = cargarCotizacion(id);\n        try {\n            c.aceptar(LocalDate.now(reloj));\n        } catch (CotizacionVencidaException e) {\n            cotizaciones.guardar(c);\n            throw e;\n        }\n        return cotizaciones.guardar(c);\n    }\n\n    /** Convierte una cotización aceptada en pedido en borrador. Verifica que el cliente siga activo. */\n    @Transactional\n    public Pedido convertirEnPedido(UUID cotizacionId) {\n        Cotizacion c = cargarCotizacion(cotizacionId);\n        clientes.exigirActivo(c.getClienteId());\n        Pedido pedido = Pedido.desdeCotizacion(c);\n        c.marcarConvertida(pedido.getId());\n        cotizaciones.guardar(c);\n        return pedidos.guardar(pedido);\n    }\n\n    /** Crea un pedido en borrador. Falla si el cliente no está activo. */\n    @Transactional\n    public Pedido crearPedido(UUID clienteId, Canal canal, String moneda, TasaIva tasa, List<LineaComando> lineas) {\n        clientes.exigirActivo(clienteId);\n        return pedidos.guardar(Pedido.crear(clienteId, canal, moneda, tasa, aLineas(lineas)));\n    }\n\n    /** Reemplaza las líneas de un pedido en borrador. */\n    @Transactional\n    public Pedido reemplazarLineas(UUID id, List<LineaComando> lineas) {\n        Pedido p = cargarPedido(id);\n        p.reemplazarLineas(aLineas(lineas));\n        return pedidos.guardar(p);\n    }\n\n    /** Confirma el pedido y publica PedidoConfirmado con el total y las líneas, para que inventario reserve las piezas. */\n    @Transactional\n    public Pedido confirmarPedido(UUID id) {\n        Pedido p = cargarPedido(id);\n        p.confirmar(Instant.now(reloj));\n        Pedido guardado = pedidos.guardar(p);\n        eventos.publicar(new EventoDominio(\"PedidoConfirmado\", id.toString(), Map.of(\n                \"pedidoId\", id.toString(),\n                \"clienteId\", p.getClienteId().toString(),\n                \"moneda\", p.getMoneda(),\n                \"total\", p.totales().total(),\n                \"lineas\", lineasParaEvento(p))));\n        return guardado;\n    }\n\n    /** Entrega el pedido y publica PedidoEntregado con las líneas, para que inventario descuente las piezas. */\n    @Transactional\n    public Pedido entregarPedido(UUID id) {\n        Pedido p = cargarPedido(id);\n        p.entregar(Instant.now(reloj));\n        Pedido guardado = pedidos.guardar(p);\n        eventos.publicar(new EventoDominio(\"PedidoEntregado\", id.toString(), Map.of(\n                \"pedidoId\", id.toString(),\n                \"clienteId\", p.getClienteId().toString(),\n                \"lineas\", lineasParaEvento(p))));\n        return guardado;\n    }\n\n    /** Artículo y cantidad de cada línea, para que inventario reserve y descuente sin consultar a ventas. */\n    private static List<Map<String, Object>> lineasParaEvento(Pedido p) {\n        return p.getLineas().stream()\n                .map(l -> Map.<String, Object>of(\n                        \"productoId\", l.getProductoId().toString(),\n                        \"cantidad\", l.getCantidad()))\n                .toList();\n    }\n\n    /** Cancela el pedido y publica PedidoCancelado con el motivo. */\n    @Transactional\n    public Pedido cancelarPedido(UUID id, MotivoCancelacion motivo) {\n        Pedido p = cargarPedido(id);\n        p.cancelar(motivo);\n        Pedido guardado = pedidos.guardar(p);\n        eventos.publicar(new EventoDominio(\"PedidoCancelado\", id.toString(), Map.of(\"motivo\", motivo.name())));\n        return guardado;\n    }\n\n    /** Registra la devolución total y publica PedidoCancelado con motivo de devolución. */\n    @Transactional\n    public Pedido devolverPedido(UUID id) {\n        Pedido p = cargarPedido(id);\n        p.devolver();\n        Pedido guardado = pedidos.guardar(p);\n        eventos.publicar(new EventoDominio(\"PedidoCancelado\", id.toString(),\n                Map.of(\"motivo\", MotivoCancelacion.DEVOLUCION_TOTAL.name())));\n        return guardado;\n    }\n\n    /** Devuelve una cotización por id. */\n    @Transactional(readOnly = true)\n    public Cotizacion obtenerCotizacion(UUID id) {\n        return cargarCotizacion(id);\n    }\n\n    /** Devuelve un pedido por id. */\n    @Transactional(readOnly = true)\n    public Pedido obtenerPedido(UUID id) {\n        return cargarPedido(id);\n    }\n\n    /** Busca pedidos con filtros opcionales. */\n    @Transactional(readOnly = true)\n    public List<Pedido> buscarPedidos(UUID clienteId, EstatusPedido estatus, Canal canal) {\n        return pedidos.buscarFiltrados(clienteId, estatus, canal);\n    }\n\n    /** Calcula las ventas netas del mes en UTC: pedidos confirmados o entregados, sin los cancelados ni devueltos, por moneda. */\n    @Transactional(readOnly = true)\n    public ResumenVentas resumenVentas(YearMonth mes) {\n        Instant desde = mes.atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();\n        Instant hasta = mes.plusMonths(1).atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();\n        List<Pedido> lista = pedidos.buscarConfirmadosEntre(desde, hasta);\n        Map<String, BigDecimal> porMoneda = lista.stream().collect(Collectors.groupingBy(\n                Pedido::getMoneda, TreeMap::new,\n                Collectors.reducing(BigDecimal.ZERO, p -> p.totales().total(), BigDecimal::add)));\n        return new ResumenVentas(mes, lista.size(), porMoneda);\n    }\n\n    /** Carga una cotización por id o lanza RecursoNoEncontradoException. */\n    private Cotizacion cargarCotizacion(UUID id) {\n        return cotizaciones.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Cotización no encontrada: \" + id));\n    }\n\n    /** Carga un pedido por id o lanza RecursoNoEncontradoException. */\n    private Pedido cargarPedido(UUID id) {\n        return pedidos.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Pedido no encontrado: \" + id));\n    }\n\n    /** Convierte los comandos en líneas del dominio. */\n    private static List<Linea> aLineas(List<LineaComando> comandos) {\n        if (comandos == null) {\n            return List.of();\n        }\n        return comandos.stream()\n                .map(c -> Linea.crear(c.productoId(), c.descripcion(), c.cantidad(), c.precioUnitario()))\n                .toList();\n    }\n\n    /** Catálogo de monedas, usado por la API para mostrar opciones válidas. */\n    public static Map<String, Integer> monedas() {\n        return Monedas.catalogo();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/application/PublicadorEventos.java": "package com.mx.josesaid.develop.pedidos.application;\n\n/** Publica eventos de dominio de ventas para que otros servicios reaccionen. */\npublic interface PublicadorEventos {\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/application/ValidadorCliente.java": "package com.mx.josesaid.develop.pedidos.application;\n\nimport java.util.UUID;\n\n/**\n * Confirma en clientes-ms que el cliente existe y está ACTIVO antes de cotizar o vender.\n *\n * <p>Lanza {@code ReglaDeNegocioException} si el cliente no existe o no está activo, y\n * {@code ServicioNoDisponibleException} si clientes-ms no responde.\n */\npublic interface ValidadorCliente {\n\n    void exigirActivo(UUID clienteId);\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/config/ClienteHttpConfig.java": "package com.mx.josesaid.develop.pedidos.config;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.web.client.RestClient;\n\n/**\n * Builder de RestClient para las llamadas a otros servicios. Spring Boot 4 no lo registra con el\n * starter de webmvc, así que se declara aquí.\n */\n@Configuration\npublic class ClienteHttpConfig {\n\n    /** Builder de RestClient con los tiempos de espera para llamar a otros servicios. */\n    @Bean\n    RestClient.Builder restClientBuilder() {\n        return RestClient.builder();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.pedidos.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code pedidos.jwt}.\n *\n * @param jwksUri URL del JWKS de usuarios-accesos-ms con la clave pública para validar tokens\n * @param duracion vida del token de acceso\n * @param emisor   valor del claim {@code iss}\n */\n@ConfigurationProperties(prefix = \"pedidos.jwt\")\npublic record PropiedadesJwt(String jwksUri, Duration duracion, String emisor) {\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/config/RelojConfig.java": "package com.mx.josesaid.develop.pedidos.config;\n\nimport java.time.Clock;\nimport java.time.ZoneId;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC, usado para las fechas de ventas. */\n    @Bean\n    Clock reloj() {\n        return Clock.system(ZoneId.of(\"America/Mexico_City\"));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/config/SeguridadConfig.java": "package com.mx.josesaid.develop.pedidos.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.pedidos.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.pedidos.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.pedidos.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad de la API sin estado. Exige JWT válido en todo, excepto salud, info y métricas. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Valida la firma con la clave pública que publica usuarios-accesos-ms (JWKS). */\n    @Bean\n    JwtDecoder jwtDecoder(PropiedadesJwt propiedades, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(propiedades.jwksUri()).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Codificador de contraseñas BCrypt. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/Canal.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** Canal por el que se realizó la venta: web, tienda o teléfono. */\npublic enum Canal { WEB, TIENDA, TELEFONO }\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/ConflictoException.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** Conflicto con el estado actual. HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Se lanza cuando la operación choca con el estado actual del documento. Se responde como conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/Cotizacion.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Cotización: BORRADOR → ENVIADA → ACEPTADA, o VENCIDA si pasa su fecha. Se convierte en pedido una sola vez. */\npublic class Cotizacion {\n\n    private final UUID id;\n    private final UUID clienteId;\n    private final Canal canal;\n    private final String moneda;\n    private final TasaIva tasa;\n    private final LocalDate vigenteHasta;\n    private final List<Linea> lineas;\n    private EstatusCotizacion estatus;\n    private UUID pedidoId;\n\n    /** Constructor privado: las cotizaciones se crean con sus fábricas. */\n    private Cotizacion(UUID id, UUID clienteId, Canal canal, String moneda, TasaIva tasa, LocalDate vigenteHasta,\n                       List<Linea> lineas, EstatusCotizacion estatus, UUID pedidoId) {\n        this.id = id;\n        this.clienteId = clienteId;\n        this.canal = canal;\n        this.moneda = moneda;\n        this.tasa = tasa;\n        this.vigenteHasta = vigenteHasta;\n        this.lineas = new ArrayList<>(lineas);\n        this.estatus = estatus;\n        this.pedidoId = pedidoId;\n    }\n\n    /** Crea una cotización en borrador. Requiere vigencia y al menos una línea. */\n    public static Cotizacion crear(UUID clienteId, Canal canal, String moneda, TasaIva tasa, LocalDate vigenteHasta,\n                                   List<Linea> lineas) {\n        validarCabecera(clienteId, canal, moneda, tasa);\n        if (vigenteHasta == null) {\n            throw new ReglaDeNegocioException(\"La vigencia de la cotización es obligatoria\");\n        }\n        if (lineas == null || lineas.isEmpty()) {\n            throw new ReglaDeNegocioException(\"La cotización requiere al menos una línea\");\n        }\n        return new Cotizacion(UUID.randomUUID(), clienteId, canal, moneda, tasa, vigenteHasta, lineas,\n                EstatusCotizacion.BORRADOR, null);\n    }\n\n    /** Reconstruye una cotización desde la base de datos sin aplicar reglas. */\n    public static Cotizacion reconstruir(UUID id, UUID clienteId, Canal canal, String moneda, TasaIva tasa,\n                                         LocalDate vigenteHasta, List<Linea> lineas, EstatusCotizacion estatus,\n                                         UUID pedidoId) {\n        return new Cotizacion(id, clienteId, canal, moneda, tasa, vigenteHasta, lineas, estatus, pedidoId);\n    }\n\n    /** Valida cliente, canal, moneda y tasa de IVA de la cotización. */\n    static void validarCabecera(UUID clienteId, Canal canal, String moneda, TasaIva tasa) {\n        if (clienteId == null) {\n            throw new ReglaDeNegocioException(\"El cliente es obligatorio\");\n        }\n        if (canal == null) {\n            throw new ReglaDeNegocioException(\"El canal es obligatorio\");\n        }\n        Monedas.decimales(moneda);\n        if (tasa == null) {\n            throw new ReglaDeNegocioException(\"La tasa de IVA es obligatoria\");\n        }\n    }\n\n    /** Envía la cotización: de borrador a enviada. */\n    public void enviar() {\n        if (estatus != EstatusCotizacion.BORRADOR) {\n            throw new ConflictoException(\"Solo una cotización en borrador puede enviarse\");\n        }\n        this.estatus = EstatusCotizacion.ENVIADA;\n    }\n\n    /** Acepta la cotización. Si ya venció, la marca VENCIDA y responde 410: no se reactiva. */\n    public void aceptar(LocalDate hoy) {\n        if (estatus == EstatusCotizacion.VENCIDA) {\n            throw new CotizacionVencidaException(\"La cotización venció; cree una nueva\");\n        }\n        if (estatus != EstatusCotizacion.ENVIADA) {\n            throw new ConflictoException(\"Solo una cotización enviada puede aceptarse\");\n        }\n        if (hoy.isAfter(vigenteHasta)) {\n            this.estatus = EstatusCotizacion.VENCIDA;\n            throw new CotizacionVencidaException(\"La cotización venció el \" + vigenteHasta);\n        }\n        this.estatus = EstatusCotizacion.ACEPTADA;\n    }\n\n    /** Verifica que pueda convertirse y registra el pedido resultante. */\n    public void marcarConvertida(UUID pedidoId) {\n        if (estatus != EstatusCotizacion.ACEPTADA) {\n            throw new ConflictoException(\"Solo una cotización aceptada puede convertirse en pedido\");\n        }\n        if (this.pedidoId != null) {\n            throw new ConflictoException(\"La cotización ya se convirtió en un pedido\");\n        }\n        this.pedidoId = pedidoId;\n    }\n\n    /** Calcula subtotal, IVA y total de la cotización. */\n    public Totales totales() {\n        return Totales.calcular(lineas, moneda, tasa);\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id del cliente. */\n    public UUID getClienteId() { return clienteId; }\n    /** Devuelve el canal. */\n    public Canal getCanal() { return canal; }\n    /** Devuelve la moneda. */\n    public String getMoneda() { return moneda; }\n    /** Devuelve la tasa de IVA. */\n    public TasaIva getTasa() { return tasa; }\n    /** Devuelve la fecha hasta la que es vigente. */\n    public LocalDate getVigenteHasta() { return vigenteHasta; }\n    /** Devuelve las líneas, en una vista de solo lectura. */\n    public List<Linea> getLineas() { return Collections.unmodifiableList(lineas); }\n    /** Devuelve el estatus. */\n    public EstatusCotizacion getEstatus() { return estatus; }\n    /** Devuelve el id del pedido creado a partir de esta cotización, o nulo. */\n    public UUID getPedidoId() { return pedidoId; }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/CotizacionRepositorio.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar cotizaciones, sin depender de JPA. */\npublic interface CotizacionRepositorio {\n    Cotizacion guardar(Cotizacion cotizacion);\n    Optional<Cotizacion> buscarPorId(UUID id);\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/CotizacionVencidaException.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** La cotización venció y no puede aceptarse. HTTP 410. */\npublic class CotizacionVencidaException extends RuntimeException {\n    /** Se lanza cuando la cotización ya venció. Responde 410. */\n    public CotizacionVencidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/EstatusCotizacion.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** Estatus de una cotización: borrador, enviada, aceptada, rechazada o vencida. */\npublic enum EstatusCotizacion { BORRADOR, ENVIADA, ACEPTADA, RECHAZADA, VENCIDA }\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/EstatusPedido.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** Estatus de un pedido: borrador, confirmado, entregado o cancelado. */\npublic enum EstatusPedido { BORRADOR, CONFIRMADO, ENTREGADO, CANCELADO }\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/Linea.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Línea de cotización o pedido. Precio y tasa quedan congelados al confirmar el pedido. */\npublic final class Linea {\n\n    private final UUID productoId;\n    private final String descripcion;\n    private final int cantidad;\n    private final BigDecimal precioUnitario;\n\n    /** Constructor privado: las líneas se crean con sus fábricas. */\n    private Linea(UUID productoId, String descripcion, int cantidad, BigDecimal precioUnitario) {\n        this.productoId = productoId;\n        this.descripcion = descripcion;\n        this.cantidad = cantidad;\n        this.precioUnitario = precioUnitario;\n    }\n\n    /** Crea una línea. Valida la cantidad y el precio. */\n    public static Linea crear(UUID productoId, String descripcion, int cantidad, BigDecimal precioUnitario) {\n        if (productoId == null) {\n            throw new ReglaDeNegocioException(\"Cada línea requiere producto\");\n        }\n        if (cantidad <= 0) {\n            throw new ReglaDeNegocioException(\"La cantidad de cada línea debe ser mayor a cero\");\n        }\n        if (precioUnitario == null || precioUnitario.signum() < 0) {\n            throw new ReglaDeNegocioException(\"El precio unitario no puede ser negativo\");\n        }\n        return new Linea(productoId, descripcion == null ? \"\" : descripcion.trim(), cantidad, precioUnitario);\n    }\n\n    /** Reconstruye una línea desde la base de datos sin aplicar reglas. */\n    public static Linea reconstruir(UUID productoId, String descripcion, int cantidad, BigDecimal precioUnitario) {\n        return new Linea(productoId, descripcion, cantidad, precioUnitario);\n    }\n\n    /** Devuelve el subtotal de la línea: cantidad por precio unitario. */\n    public BigDecimal subtotal() {\n        return precioUnitario.multiply(BigDecimal.valueOf(cantidad));\n    }\n\n    /** Devuelve el id del producto. */\n    public UUID getProductoId() { return productoId; }\n    /** Devuelve la descripción. */\n    public String getDescripcion() { return descripcion; }\n    /** Devuelve la cantidad. */\n    public int getCantidad() { return cantidad; }\n    /** Devuelve el precio unitario. */\n    public BigDecimal getPrecioUnitario() { return precioUnitario; }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/Monedas.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport java.util.Map;\n\n/** Catálogo de monedas con sus decimales. Agregar una moneda es configuración de este mapa. */\npublic final class Monedas {\n\n    private static final Map<String, Integer> DECIMALES = Map.of(\"MXN\", 2, \"USD\", 2);\n\n    /** Clase de utilidad; no se instancia. */\n    private Monedas() {\n    }\n\n    /** Devuelve las monedas aceptadas con sus decimales. */\n    public static Map<String, Integer> catalogo() {\n        return DECIMALES;\n    }\n\n    /** Devuelve los decimales de una moneda. Falla si la moneda no está en el catálogo. */\n    public static int decimales(String moneda) {\n        Integer d = DECIMALES.get(moneda);\n        if (d == null) {\n            throw new ReglaDeNegocioException(\"La moneda no está en el catálogo: \" + moneda);\n        }\n        return d;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/MotivoCancelacion.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** DEVOLUCION_TOTAL solo lo registra la devolución; la cancelación manual no puede usarlo. */\npublic enum MotivoCancelacion { CANCELACION_CLIENTE, ERROR_CAPTURA, DEVOLUCION_TOTAL }\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/Pedido.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.UUID;\n\n/**\n * Pedido: BORRADOR → CONFIRMADO → ENTREGADO. CANCELADO se alcanza desde BORRADOR o CONFIRMADO.\n * Una devolución lleva ENTREGADO a CANCELADO con motivo DEVOLUCION_TOTAL. Nada se borra.\n */\npublic class Pedido {\n\n    private final UUID id;\n    private final UUID clienteId;\n    private final UUID cotizacionId;\n    private final Canal canal;\n    private final String moneda;\n    private final TasaIva tasa;\n    private EstatusPedido estatus;\n    private List<Linea> lineas;\n    private Instant fechaConfirmacion;\n    private Instant fechaEntrega;\n    private MotivoCancelacion motivoCancelacion;\n\n    /** Constructor privado: los pedidos se crean con sus fábricas. */\n    private Pedido(UUID id, UUID clienteId, UUID cotizacionId, Canal canal, String moneda, TasaIva tasa,\n                   EstatusPedido estatus, List<Linea> lineas, Instant fechaConfirmacion, Instant fechaEntrega,\n                   MotivoCancelacion motivoCancelacion) {\n        this.id = id;\n        this.clienteId = clienteId;\n        this.cotizacionId = cotizacionId;\n        this.canal = canal;\n        this.moneda = moneda;\n        this.tasa = tasa;\n        this.estatus = estatus;\n        this.lineas = new ArrayList<>(lineas);\n        this.fechaConfirmacion = fechaConfirmacion;\n        this.fechaEntrega = fechaEntrega;\n        this.motivoCancelacion = motivoCancelacion;\n    }\n\n    /** Crea un pedido en borrador. Requiere al menos una línea. */\n    public static Pedido crear(UUID clienteId, Canal canal, String moneda, TasaIva tasa, List<Linea> lineas) {\n        Cotizacion.validarCabecera(clienteId, canal, moneda, tasa);\n        if (lineas == null || lineas.isEmpty()) {\n            throw new ReglaDeNegocioException(\"El pedido requiere al menos una línea\");\n        }\n        return new Pedido(UUID.randomUUID(), clienteId, null, canal, moneda, tasa, EstatusPedido.BORRADOR, lineas,\n                null, null, null);\n    }\n\n    /** Crea el pedido en borrador a partir de una cotización aceptada. */\n    public static Pedido desdeCotizacion(Cotizacion c) {\n        if (c.getEstatus() != EstatusCotizacion.ACEPTADA || c.getPedidoId() != null) {\n            throw new ConflictoException(\"Solo una cotización aceptada y no convertida puede pasar a pedido\");\n        }\n        return new Pedido(UUID.randomUUID(), c.getClienteId(), c.getId(), c.getCanal(), c.getMoneda(), c.getTasa(),\n                EstatusPedido.BORRADOR, c.getLineas(), null, null, null);\n    }\n\n    /** Reconstruye un pedido desde la base de datos sin aplicar reglas. */\n    public static Pedido reconstruir(UUID id, UUID clienteId, UUID cotizacionId, Canal canal, String moneda,\n                                     TasaIva tasa, EstatusPedido estatus, List<Linea> lineas, Instant fechaConfirmacion,\n                                     Instant fechaEntrega, MotivoCancelacion motivoCancelacion) {\n        return new Pedido(id, clienteId, cotizacionId, canal, moneda, tasa, estatus, lineas, fechaConfirmacion,\n                fechaEntrega, motivoCancelacion);\n    }\n\n    /** Reemplaza las líneas. Solo en borrador. */\n    public void reemplazarLineas(List<Linea> nuevas) {\n        if (estatus != EstatusPedido.BORRADOR) {\n            throw new ConflictoException(\"Solo un pedido en borrador admite cambios en sus líneas\");\n        }\n        if (nuevas == null) {\n            throw new ReglaDeNegocioException(\"Las líneas son obligatorias\");\n        }\n        this.lineas = new ArrayList<>(nuevas);\n    }\n\n    /** Confirma el pedido. Solo desde borrador y con al menos una línea de cantidad mayor a cero. */\n    public void confirmar(Instant ahora) {\n        if (estatus != EstatusPedido.BORRADOR) {\n            throw new ConflictoException(\"Solo un pedido en borrador puede confirmarse\");\n        }\n        if (lineas.isEmpty() || lineas.stream().noneMatch(l -> l.getCantidad() > 0)) {\n            throw new ReglaDeNegocioException(\"Confirmar requiere al menos una línea con cantidad mayor a cero\");\n        }\n        this.estatus = EstatusPedido.CONFIRMADO;\n        this.fechaConfirmacion = ahora;\n    }\n\n    /** Marca el pedido como entregado. Solo desde confirmado. */\n    public void entregar(Instant ahora) {\n        if (estatus != EstatusPedido.CONFIRMADO) {\n            throw new ConflictoException(\"Solo un pedido confirmado puede entregarse\");\n        }\n        this.estatus = EstatusPedido.ENTREGADO;\n        this.fechaEntrega = ahora;\n    }\n\n    /** Cancela el pedido desde borrador o confirmado. El motivo es obligatorio y la devolución tiene su propio camino. */\n    public void cancelar(MotivoCancelacion motivo) {\n        if (motivo == null) {\n            throw new SolicitudInvalidaException(\"El motivo de cancelación es obligatorio\");\n        }\n        if (motivo == MotivoCancelacion.DEVOLUCION_TOTAL) {\n            throw new SolicitudInvalidaException(\"La devolución se registra con su propio endpoint\");\n        }\n        if (estatus != EstatusPedido.BORRADOR && estatus != EstatusPedido.CONFIRMADO) {\n            throw new ConflictoException(\"Solo un pedido en borrador o confirmado puede cancelarse\");\n        }\n        this.estatus = EstatusPedido.CANCELADO;\n        this.motivoCancelacion = motivo;\n    }\n\n    /** Devolución total: solo desde ENTREGADO. */\n    public void devolver() {\n        if (estatus != EstatusPedido.ENTREGADO) {\n            throw new ConflictoException(\"Solo un pedido entregado puede devolverse\");\n        }\n        this.estatus = EstatusPedido.CANCELADO;\n        this.motivoCancelacion = MotivoCancelacion.DEVOLUCION_TOTAL;\n    }\n\n    /** Calcula subtotal, IVA y total del pedido. */\n    public Totales totales() {\n        return Totales.calcular(lineas, moneda, tasa);\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id del cliente. */\n    public UUID getClienteId() { return clienteId; }\n    /** Devuelve el id de la cotización de origen, si existe. */\n    public UUID getCotizacionId() { return cotizacionId; }\n    /** Devuelve el canal. */\n    public Canal getCanal() { return canal; }\n    /** Devuelve la moneda. */\n    public String getMoneda() { return moneda; }\n    /** Devuelve la tasa de IVA. */\n    public TasaIva getTasa() { return tasa; }\n    /** Devuelve el estatus. */\n    public EstatusPedido getEstatus() { return estatus; }\n    /** Devuelve las líneas, en una vista de solo lectura. */\n    public List<Linea> getLineas() { return Collections.unmodifiableList(lineas); }\n    /** Devuelve la fecha de confirmación en UTC, o nula. */\n    public Instant getFechaConfirmacion() { return fechaConfirmacion; }\n    /** Devuelve la fecha de entrega en UTC, o nula. */\n    public Instant getFechaEntrega() { return fechaEntrega; }\n    /** Devuelve el motivo de cancelación, o nulo. */\n    public MotivoCancelacion getMotivoCancelacion() { return motivoCancelacion; }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/PedidoRepositorio.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar pedidos, sin depender de JPA. */\npublic interface PedidoRepositorio {\n    Pedido guardar(Pedido pedido);\n    Optional<Pedido> buscarPorId(UUID id);\n    List<Pedido> buscarFiltrados(UUID clienteId, EstatusPedido estatus, Canal canal);\n    List<Pedido> buscarConfirmadosEntre(Instant desde, Instant hasta);\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** El recurso no existe. HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Se lanza cuando no existe el recurso pedido. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** Una operación viola una regla de negocio. HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Se lanza cuando una regla de negocio no se cumple. El mensaje se muestra al cliente. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/ServicioNoDisponibleException.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** No se pudo consultar un servicio del que depende la operación. Se traduce a HTTP 503. */\npublic class ServicioNoDisponibleException extends RuntimeException {\n\n    /** Se lanza cuando un servicio externo no responde. Se responde como servicio no disponible. */\n    public ServicioNoDisponibleException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/SolicitudInvalidaException.java": "package com.mx.josesaid.develop.pedidos.domain;\n\n/** Datos de forma inválidos, como un motivo fuera de catálogo. HTTP 400. */\npublic class SolicitudInvalidaException extends RuntimeException {\n    /** Se lanza cuando la solicitud no es válida. */\n    public SolicitudInvalidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/TasaIva.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport java.math.BigDecimal;\n\n/** Tasas de IVA del catálogo. IVA_FRONTERIZO está pendiente de validación con contabilidad. */\npublic enum TasaIva {\n    IVA_GENERAL(new BigDecimal(\"0.16\")),\n    IVA_FRONTERIZO(new BigDecimal(\"0.08\")),\n    IVA_EXENTO(BigDecimal.ZERO);\n\n    private final BigDecimal valor;\n\n    TasaIva(BigDecimal valor) {\n        this.valor = valor;\n    }\n\n    /** Devuelve el valor decimal de la tasa, por ejemplo 0.16 para el IVA general. */\n    public BigDecimal valor() {\n        return valor;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/domain/Totales.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport static java.math.BigDecimal.ZERO;\nimport static java.math.RoundingMode.HALF_EVEN;\n\nimport java.math.BigDecimal;\nimport java.util.List;\n\n/**\n * Subtotal, IVA y total redondeados a los decimales de la moneda con redondeo bancario.\n *\n * @param subtotal subtotal antes de impuestos, de tipo {@code BigDecimal}.\n * @param iva iva, de tipo {@code BigDecimal}.\n * @param total importe total, de tipo {@code BigDecimal}.\n */\npublic record Totales(BigDecimal subtotal, BigDecimal iva, BigDecimal total) {\n\n    /** Calcula subtotal, IVA y total. Cada cifra se redondea a los decimales de la moneda con redondeo bancario. */\n    public static Totales calcular(List<Linea> lineas, String moneda, TasaIva tasa) {\n        int decimales = Monedas.decimales(moneda);\n        BigDecimal subtotal = lineas.stream().map(Linea::subtotal).reduce(ZERO, BigDecimal::add)\n                .setScale(decimales, HALF_EVEN);\n        BigDecimal iva = subtotal.multiply(tasa.valor()).setScale(decimales, HALF_EVEN);\n        return new Totales(subtotal, iva, subtotal.add(iva));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/clientes/ClientesRestValidador.java": "package com.mx.josesaid.develop.pedidos.infrastructure.clientes;\n\nimport com.mx.josesaid.develop.pedidos.application.ValidadorCliente;\nimport com.mx.josesaid.develop.pedidos.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.pedidos.domain.ServicioNoDisponibleException;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.stereotype.Component;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\nimport org.springframework.web.client.RestClientException;\nimport org.springframework.web.client.RestClientResponseException;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Consulta {@code GET /v1/clientes/{id}} en clientes-ms con el mismo token del usuario que hizo\n * la petición. clientes-ms exige rol VENTAS o ADMIN, igual que la operación de pedidos.\n */\n@Component\npublic class ClientesRestValidador implements ValidadorCliente {\n\n    private final RestClient http;\n    private final ObjectMapper mapper;\n\n    /** Recibe el constructor de clientes HTTP, la URL de clientes-ms y el serializador JSON. */\n    public ClientesRestValidador(RestClient.Builder builder,\n                                 @Value(\"${clientes.url:http://clientes-ms:8080}\") String url,\n                                 ObjectMapper mapper) {\n        this.http = builder.baseUrl(url).build();\n        this.mapper = mapper;\n    }\n\n    /** Verifica en clientes-ms que el cliente exista y esté activo. Usa el token del usuario que hizo la petición. */\n    @Override\n    public void exigirActivo(UUID clienteId) {\n        String cuerpo;\n        try {\n            cuerpo = http.get()\n                    .uri(\"/v1/clientes/{id}\", clienteId)\n                    .header(\"Authorization\", \"Bearer \" + tokenActual())\n                    .retrieve()\n                    .body(String.class);\n        } catch (HttpClientErrorException.NotFound e) {\n            throw new ReglaDeNegocioException(\"El cliente no existe\");\n        } catch (RestClientResponseException e) {\n            throw new ServicioNoDisponibleException(\n                    \"clientes-ms respondió \" + e.getStatusCode().value() + \"; intente de nuevo\");\n        } catch (RestClientException e) {\n            throw new ServicioNoDisponibleException(\"No se pudo consultar clientes-ms; intente de nuevo\");\n        }\n        Map<?, ?> respuesta;\n        try {\n            respuesta = mapper.readValue(cuerpo, Map.class);\n        } catch (RuntimeException e) {\n            throw new ServicioNoDisponibleException(\"Respuesta inválida de clientes-ms; intente de nuevo\");\n        }\n        if (respuesta == null) {\n            throw new ServicioNoDisponibleException(\"Respuesta vacía de clientes-ms; intente de nuevo\");\n        }\n        if (!\"ACTIVO\".equals(respuesta.get(\"estatus\"))) {\n            throw new ReglaDeNegocioException(\"El cliente no está activo\");\n        }\n    }\n\n    /** Obtiene el token del usuario autenticado para llamar a clientes-ms. */\n    private static String tokenActual() {\n        var autenticacion = SecurityContextHolder.getContext().getAuthentication();\n        if (autenticacion instanceof JwtAuthenticationToken jwt) {\n            return jwt.getToken().getTokenValue();\n        }\n        throw new ServicioNoDisponibleException(\"No hay token para consultar clientes-ms\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/idempotencia/Idempotencia.java": "package com.mx.josesaid.develop.pedidos.infrastructure.idempotencia;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.pedidos.domain.ConflictoException;\nimport com.mx.josesaid.develop.pedidos.domain.ReglaDeNegocioException;\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.util.HexFormat;\nimport java.util.function.Supplier;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.stereotype.Component;\n\n/**\n * Hace seguras de reintentar las altas que reciben la cabecera Idempotency-Key.\n * Misma clave y misma petición: devuelve la respuesta original, sin crear nada nuevo.\n * Misma clave con otra petición: 422. Clave todavía en proceso: 409.\n * Sin cabecera: la operación se ejecuta como siempre.\n */\n@Component\npublic class Idempotencia {\n\n    public static final String CABECERA = \"Idempotency-Key\";\n\n    private final RegistroIdempotencia registro;\n    private final ObjectMapper mapper;\n\n    /** Recibe el registro de claves y el serializador JSON. */\n    public Idempotencia(RegistroIdempotencia registro, ObjectMapper mapper) {\n        this.registro = registro;\n        this.mapper = mapper;\n    }\n\n    /** Ejecuta una operación una sola vez por Idempotency-Key. Una misma clave con la misma petición devuelve la respuesta guardada; con otra petición, rechaza. Si la operación falla, libera la clave para reintentar. */\n    public <T> ResponseEntity<?> ejecutar(String clave, String ruta, Object peticion,\n                                          HttpStatus estado, Supplier<T> operacion) {\n        if (clave == null || clave.isBlank()) {\n            return ResponseEntity.status(estado).body(operacion.get());\n        }\n        String huella = huella(ruta, peticion);\n        if (!registro.reservar(clave, huella)) {\n            RegistroIdempotencia.Registro previo = registro.buscar(clave)\n                    .orElseThrow(() -> new ConflictoException(\"La Idempotency-Key ya no está disponible. Intente de nuevo.\"));\n            if (!previo.huella().equals(huella)) {\n                throw new ReglaDeNegocioException(\"La Idempotency-Key ya se usó con una petición distinta.\");\n            }\n            if (!previo.completada()) {\n                throw new ConflictoException(\"La petición con esta Idempotency-Key aún se está procesando.\");\n            }\n            return ResponseEntity.status(previo.estatus())\n                    .contentType(MediaType.APPLICATION_JSON)\n                    .body(previo.cuerpo());\n        }\n        T cuerpo;\n        try {\n            cuerpo = operacion.get();\n        } catch (RuntimeException e) {\n            registro.liberar(clave);\n            throw e;\n        }\n        registro.completar(clave, estado.value(), serializar(cuerpo));\n        return ResponseEntity.status(estado).body(cuerpo);\n    }\n\n    /** Calcula la huella SHA-256 de la ruta y el cuerpo de la petición, para detectar si una clave se reutiliza con otra petición. */\n    private String huella(String ruta, Object peticion) {\n        try {\n            byte[] digest = MessageDigest.getInstance(\"SHA-256\")\n                    .digest((ruta + \"\\n\" + mapper.writeValueAsString(peticion)).getBytes(StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(digest);\n        } catch (JsonProcessingException | NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"No se pudo calcular la huella de la petición\", e);\n        }\n    }\n\n    /** Convierte la respuesta en JSON para guardarla. */\n    private String serializar(Object cuerpo) {\n        try {\n            return mapper.writeValueAsString(cuerpo);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo guardar la respuesta idempotente\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/idempotencia/RegistroIdempotencia.java": "package com.mx.josesaid.develop.pedidos.infrastructure.idempotencia;\n\nimport java.sql.Timestamp;\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Optional;\nimport org.springframework.dao.DuplicateKeyException;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\n\n/**\n * Guarda el estado de cada clave Idempotency-Key. Una respuesta completada se conserva 24 horas.\n * Una reserva que nunca se completó (la petición murió a medio camino) se puede retomar tras\n * {@link #CONCESION_RESERVA}, para que la clave no quede bloqueada todo el día.\n */\n@Repository\nclass RegistroIdempotencia {\n\n    static final Duration VIGENCIA = Duration.ofHours(24);\n    static final Duration CONCESION_RESERVA = Duration.ofMinutes(2);\n\n    /**\n     * Fila guardada para una clave: huella, estatus HTTP, cuerpo de la respuesta y si ya terminó.\n     *\n     * @param huella huella, de tipo {@code String}.\n     * @param estatus estado actual del registro, de tipo {@code int}.\n     * @param cuerpo contenido principal del mensaje, de tipo {@code String}.\n     * @param completada completada, de tipo {@code boolean}.\n     */\n    record Registro(String huella, int estatus, String cuerpo, boolean completada) {}\n\n    private final JdbcTemplate jdbc;\n    private final Clock reloj;\n\n    RegistroIdempotencia(JdbcTemplate jdbc, Clock reloj) {\n        this.jdbc = jdbc;\n        this.reloj = reloj;\n    }\n\n    /** Busca el registro de una clave que sigue vigente. */\n    Optional<Registro> buscar(String clave) {\n        return jdbc.query(\n                \"SELECT huella, estatus_http, cuerpo, completada FROM idempotencia WHERE clave = ? AND creado_utc > ?\",\n                (rs, n) -> new Registro(rs.getString(1), rs.getInt(2), rs.getString(3), rs.getBoolean(4)),\n                clave, enTiempo(vencimiento())).stream().findFirst();\n    }\n\n    /**\n     * Reserva la clave. Devuelve false si otra petición la tiene en curso o ya terminó.\n     * Si la reserva existente nunca se completó y su concesión venció, la retoma.\n     */\n    boolean reservar(String clave, String huella) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE creado_utc <= ?\", enTiempo(vencimiento()));\n        try {\n            jdbc.update(\"INSERT INTO idempotencia (clave, huella, estatus_http, cuerpo, completada, creado_utc) VALUES (?, ?, 0, NULL, FALSE, ?)\",\n                    clave, huella, enTiempo(reloj.instant()));\n            return true;\n        } catch (DuplicateKeyException e) {\n            return retomarReservaVencida(clave, huella);\n        }\n    }\n\n    /** Solo una petición gana la retoma: el UPDATE es condicional, así que es atómico. */\n    private boolean retomarReservaVencida(String clave, String huella) {\n        Instant ahora = reloj.instant();\n        int filas = jdbc.update(\n                \"UPDATE idempotencia SET huella = ?, creado_utc = ? WHERE clave = ? AND completada = FALSE AND creado_utc <= ?\",\n                huella, enTiempo(ahora), clave, enTiempo(ahora.minus(CONCESION_RESERVA)));\n        return filas == 1;\n    }\n\n    /** Guarda la respuesta de una operación terminada. */\n    void completar(String clave, int estatus, String cuerpo) {\n        jdbc.update(\"UPDATE idempotencia SET estatus_http = ?, cuerpo = ?, completada = TRUE WHERE clave = ?\",\n                estatus, cuerpo, clave);\n    }\n\n    /** Libera la reserva cuando la operación falló, para que el cliente pueda reintentar. */\n    void liberar(String clave) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE clave = ? AND completada = FALSE\", clave);\n    }\n\n    /** Calcula el límite de vigencia de las claves. */\n    private Instant vencimiento() {\n        return reloj.instant().minus(VIGENCIA);\n    }\n\n    /** Convierte un instante a Timestamp para la base de datos. */\n    private static Timestamp enTiempo(Instant instante) {\n        return Timestamp.from(instante);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/indicadores/PublicadorIndicadoresVentas.java": "package com.mx.josesaid.develop.pedidos.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms el indicador \"ventas del mes\" del área de ventas.\n *\n * <p>Ventas = suma de líneas de pedidos en MXN con estatus CONFIRMADO o ENTREGADO, con IVA incluido,\n * asignadas al mes de su confirmación (hora de la Ciudad de México). En cada ciclo se recalculan el mes\n * actual y el anterior. Reportes hace upsert por área, nombre y periodo, así que un valor repetido no\n * duplica nada. Es una foto del periodo, no un evento: no pasa por el outbox. Si un envío falla, el\n * siguiente ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresVentas {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresVentas.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"VENTAS_ATENCION_CLIENTES\";\n    public static final String NOMBRE = \"ventas_mes\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_VENTAS = \"\"\"\n            SELECT COALESCE(SUM(ROUND(l.cantidad * l.precio_unitario *\n                   (1 + CASE p.tasa WHEN 'IVA_GENERAL' THEN 0.16 WHEN 'IVA_FRONTERIZO' THEN 0.08 ELSE 0 END), 2)), 0)\n            FROM pedidos p\n            JOIN lineas_pedido l ON l.pedido_id = p.id\n            WHERE p.estatus IN ('CONFIRMADO', 'ENTREGADO')\n              AND p.moneda = 'MXN'\n              AND p.fecha_confirmacion IS NOT NULL\n              AND TO_CHAR(p.fecha_confirmacion AT TIME ZONE 'America/Mexico_City', 'YYYY-MM') = ?\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para sumar ventas, Kafka para publicar, el serializador, el reloj y el tópico. */\n    public PublicadorIndicadoresVentas(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                       ObjectMapper mapper, Clock reloj,\n                                       @Value(\"${pedidos.indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Publica las ventas netas del mes actual y del anterior. */\n    @Scheduled(fixedDelayString = \"${pedidos.indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${pedidos.indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        YearMonth actual = YearMonth.now(reloj.withZone(ZONA));\n        publicarPeriodo(actual.minusMonths(1).toString());\n        publicarPeriodo(actual.toString());\n    }\n\n    /** Calcula y envía el indicador de un mes (\"AAAA-MM\"). Un fallo se registra y se reintenta en el siguiente ciclo. */\n    public void publicarPeriodo(String periodo) {\n        BigDecimal valor = jdbc.queryForObject(SQL_VENTAS, BigDecimal.class, periodo);\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, NOMBRE, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + NOMBRE + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, NOMBRE, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", NOMBRE, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area área de negocio a la que pertenece, de tipo {@code String}.\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param periodo periodo de referencia (por ejemplo, año y mes), de tipo {@code String}.\n     * @param valor valor registrado, de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc fecha y hora (UTC) de la última actualización de la fuente, de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.pedidos.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el id del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el contenido JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.pedidos.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla del outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.pedidos.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.pedidos.application.EventoDominio;\nimport com.mx.josesaid.develop.pedidos.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el serializador JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.pedidos.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"pedidos.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si el envío falla, el evento queda para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${pedidos.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/persistence/CotizacionEntity.java": "package com.mx.josesaid.develop.pedidos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.pedidos.domain.Canal;\nimport com.mx.josesaid.develop.pedidos.domain.Cotizacion;\nimport com.mx.josesaid.develop.pedidos.domain.EstatusCotizacion;\nimport com.mx.josesaid.develop.pedidos.domain.TasaIva;\nimport jakarta.persistence.CollectionTable;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.ElementCollection;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.OrderColumn;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Fila de la tabla de cotizaciones, con sus líneas embebidas. */\n@Entity\n@Table(name = \"cotizaciones\")\npublic class CotizacionEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"cliente_id\", nullable = false)\n    private UUID clienteId;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 10)\n    private Canal canal;\n\n    @Column(nullable = false, length = 3)\n    private String moneda;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 20)\n    private TasaIva tasa;\n\n    @Column(name = \"vigente_hasta\", nullable = false)\n    private LocalDate vigenteHasta;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 12)\n    private EstatusCotizacion estatus;\n\n    @Column(name = \"pedido_id\", unique = true)\n    private UUID pedidoId;\n\n    @Version\n    private Long version;\n\n    @ElementCollection(fetch = FetchType.EAGER)\n    @CollectionTable(name = \"lineas_cotizacion\", joinColumns = @JoinColumn(name = \"cotizacion_id\"))\n    @OrderColumn(name = \"posicion\")\n    private List<LineaEmbebible> lineas = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected CotizacionEntity() {\n    }\n\n    /** Crea una fila a partir de una cotización del dominio. */\n    static CotizacionEntity nueva(Cotizacion c) {\n        CotizacionEntity e = new CotizacionEntity();\n        e.id = c.getId();\n        e.actualizar(c);\n        return e;\n    }\n\n    /** Actualiza la fila con los datos de la cotización. */\n    void actualizar(Cotizacion c) {\n        this.clienteId = c.getClienteId();\n        this.canal = c.getCanal();\n        this.moneda = c.getMoneda();\n        this.tasa = c.getTasa();\n        this.vigenteHasta = c.getVigenteHasta();\n        this.estatus = c.getEstatus();\n        this.pedidoId = c.getPedidoId();\n        this.lineas.clear();\n        c.getLineas().forEach(l -> this.lineas.add(new LineaEmbebible(l)));\n    }\n\n    /** Convierte la fila en la cotización del dominio. */\n    Cotizacion aDominio() {\n        return Cotizacion.reconstruir(id, clienteId, canal, moneda, tasa, vigenteHasta,\n                lineas.stream().map(LineaEmbebible::aLinea).toList(), estatus, pedidoId);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/persistence/CotizacionJpaRepository.java": "package com.mx.josesaid.develop.pedidos.infrastructure.persistence;\n\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de cotizaciones con Spring Data JPA. */\npublic interface CotizacionJpaRepository extends JpaRepository<CotizacionEntity, UUID> {\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/persistence/CotizacionRepositorioJpa.java": "package com.mx.josesaid.develop.pedidos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.pedidos.domain.Cotizacion;\nimport com.mx.josesaid.develop.pedidos.domain.CotizacionRepositorio;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Repository;\n\n/** Implementa el puerto de cotizaciones con JPA. */\n@Repository\npublic class CotizacionRepositorioJpa implements CotizacionRepositorio {\n\n    private final CotizacionJpaRepository jpa;\n\n    /** Recibe el repositorio JPA de cotizaciones. */\n    public CotizacionRepositorioJpa(CotizacionJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda una cotización y devuelve la guardada. */\n    @Override\n    public Cotizacion guardar(Cotizacion cotizacion) {\n        CotizacionEntity e = jpa.findById(cotizacion.getId())\n                .map(existente -> {\n                    existente.actualizar(cotizacion);\n                    return existente;\n                })\n                .orElseGet(() -> CotizacionEntity.nueva(cotizacion));\n        return jpa.save(e).aDominio();\n    }\n\n    /** Busca una cotización por id. */\n    @Override\n    public Optional<Cotizacion> buscarPorId(UUID id) {\n        return jpa.findById(id).map(CotizacionEntity::aDominio);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/persistence/LineaEmbebible.java": "package com.mx.josesaid.develop.pedidos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.pedidos.domain.Linea;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Embeddable;\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Línea guardada dentro de la cotización o del pedido. */\n@Embeddable\npublic class LineaEmbebible {\n\n    @Column(name = \"producto_id\", nullable = false)\n    private UUID productoId;\n\n    @Column(nullable = false, length = 200)\n    private String descripcion;\n\n    @Column(nullable = false)\n    private int cantidad;\n\n    @Column(name = \"precio_unitario\", nullable = false, precision = 14, scale = 2)\n    private BigDecimal precioUnitario;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected LineaEmbebible() {\n    }\n\n    LineaEmbebible(Linea linea) {\n        this.productoId = linea.getProductoId();\n        this.descripcion = linea.getDescripcion();\n        this.cantidad = linea.getCantidad();\n        this.precioUnitario = linea.getPrecioUnitario();\n    }\n\n    /** Convierte la línea guardada en la línea del dominio. */\n    Linea aLinea() {\n        return Linea.reconstruir(productoId, descripcion, cantidad, precioUnitario);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/persistence/PedidoEntity.java": "package com.mx.josesaid.develop.pedidos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.pedidos.domain.Canal;\nimport com.mx.josesaid.develop.pedidos.domain.EstatusPedido;\nimport com.mx.josesaid.develop.pedidos.domain.MotivoCancelacion;\nimport com.mx.josesaid.develop.pedidos.domain.Pedido;\nimport com.mx.josesaid.develop.pedidos.domain.TasaIva;\nimport jakarta.persistence.CollectionTable;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.ElementCollection;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.OrderColumn;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Fila de la tabla de pedidos, con sus líneas embebidas. */\n@Entity\n@Table(name = \"pedidos\")\npublic class PedidoEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"cliente_id\", nullable = false)\n    private UUID clienteId;\n\n    @Column(name = \"cotizacion_id\", unique = true)\n    private UUID cotizacionId;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 10)\n    private Canal canal;\n\n    @Column(nullable = false, length = 3)\n    private String moneda;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 20)\n    private TasaIva tasa;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 12)\n    private EstatusPedido estatus;\n\n    @Column(name = \"fecha_confirmacion\")\n    private Instant fechaConfirmacion;\n\n    @Column(name = \"fecha_entrega\")\n    private Instant fechaEntrega;\n\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"motivo_cancelacion\", length = 25)\n    private MotivoCancelacion motivoCancelacion;\n\n    @Version\n    private Long version;\n\n    @ElementCollection(fetch = FetchType.EAGER)\n    @CollectionTable(name = \"lineas_pedido\", joinColumns = @JoinColumn(name = \"pedido_id\"))\n    @OrderColumn(name = \"posicion\")\n    private List<LineaEmbebible> lineas = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected PedidoEntity() {\n    }\n\n    /** Crea una fila a partir de un pedido del dominio. */\n    static PedidoEntity nuevo(Pedido p) {\n        PedidoEntity e = new PedidoEntity();\n        e.id = p.getId();\n        e.actualizar(p);\n        return e;\n    }\n\n    /** Actualiza la fila con los datos del pedido. */\n    void actualizar(Pedido p) {\n        this.clienteId = p.getClienteId();\n        this.cotizacionId = p.getCotizacionId();\n        this.canal = p.getCanal();\n        this.moneda = p.getMoneda();\n        this.tasa = p.getTasa();\n        this.estatus = p.getEstatus();\n        this.fechaConfirmacion = p.getFechaConfirmacion();\n        this.fechaEntrega = p.getFechaEntrega();\n        this.motivoCancelacion = p.getMotivoCancelacion();\n        this.lineas.clear();\n        p.getLineas().forEach(l -> this.lineas.add(new LineaEmbebible(l)));\n    }\n\n    /** Convierte la fila en el pedido del dominio. */\n    Pedido aDominio() {\n        return Pedido.reconstruir(id, clienteId, cotizacionId, canal, moneda, tasa, estatus,\n                lineas.stream().map(LineaEmbebible::aLinea).toList(),\n                fechaConfirmacion, fechaEntrega, motivoCancelacion);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/persistence/PedidoJpaRepository.java": "package com.mx.josesaid.develop.pedidos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.pedidos.domain.EstatusPedido;\nimport java.time.Instant;\nimport java.util.Collection;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.JpaSpecificationExecutor;\nimport org.springframework.data.jpa.repository.Query;\nimport org.springframework.data.repository.query.Param;\n\n/** Acceso a la tabla de pedidos con Spring Data JPA y consultas con filtros. */\npublic interface PedidoJpaRepository extends JpaRepository<PedidoEntity, UUID>, JpaSpecificationExecutor<PedidoEntity> {\n\n    /** Devuelve los pedidos con esos estatus confirmados dentro de un rango de fechas. */\n    @Query(\"select p from PedidoEntity p where p.estatus in :estatus \"\n            + \"and p.fechaConfirmacion >= :desde and p.fechaConfirmacion < :hasta\")\n    List<PedidoEntity> buscarVigentesEntre(@Param(\"estatus\") Collection<EstatusPedido> estatus,\n                                           @Param(\"desde\") Instant desde,\n                                           @Param(\"hasta\") Instant hasta);\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/infrastructure/persistence/PedidoRepositorioJpa.java": "package com.mx.josesaid.develop.pedidos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.pedidos.domain.Canal;\nimport com.mx.josesaid.develop.pedidos.domain.EstatusPedido;\nimport com.mx.josesaid.develop.pedidos.domain.Pedido;\nimport com.mx.josesaid.develop.pedidos.domain.PedidoRepositorio;\nimport jakarta.persistence.criteria.Predicate;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.domain.Specification;\nimport org.springframework.stereotype.Repository;\n\n/** Implementa el puerto de pedidos con JPA. */\n@Repository\npublic class PedidoRepositorioJpa implements PedidoRepositorio {\n\n    private final PedidoJpaRepository jpa;\n\n    /** Recibe el repositorio JPA de pedidos. */\n    public PedidoRepositorioJpa(PedidoJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un pedido y devuelve el guardado. */\n    @Override\n    public Pedido guardar(Pedido pedido) {\n        PedidoEntity e = jpa.findById(pedido.getId())\n                .map(existente -> {\n                    existente.actualizar(pedido);\n                    return existente;\n                })\n                .orElseGet(() -> PedidoEntity.nuevo(pedido));\n        return jpa.save(e).aDominio();\n    }\n\n    /** Busca un pedido por id. */\n    @Override\n    public Optional<Pedido> buscarPorId(UUID id) {\n        return jpa.findById(id).map(PedidoEntity::aDominio);\n    }\n\n    /** Busca pedidos por cliente, estatus y canal. Cada filtro es opcional. */\n    @Override\n    public List<Pedido> buscarFiltrados(UUID clienteId, EstatusPedido estatus, Canal canal) {\n        Specification<PedidoEntity> spec = (raiz, consulta, cb) -> {\n            List<Predicate> condiciones = new ArrayList<>();\n            if (clienteId != null) {\n                condiciones.add(cb.equal(raiz.get(\"clienteId\"), clienteId));\n            }\n            if (estatus != null) {\n                condiciones.add(cb.equal(raiz.get(\"estatus\"), estatus));\n            }\n            if (canal != null) {\n                condiciones.add(cb.equal(raiz.get(\"canal\"), canal));\n            }\n            return cb.and(condiciones.toArray(new Predicate[0]));\n        };\n        return jpa.findAll(spec).stream().map(PedidoEntity::aDominio).toList();\n    }\n\n    /** Devuelve los pedidos confirmados dentro de un rango de fechas. */\n    @Override\n    public List<Pedido> buscarConfirmadosEntre(Instant desde, Instant hasta) {\n        return jpa.buscarVigentesEntre(List.of(EstatusPedido.CONFIRMADO, EstatusPedido.ENTREGADO), desde, hasta)\n                .stream().map(PedidoEntity::aDominio).toList();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.pedidos.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido o el token fue rechazado. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.pedidos.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"pedidos-ventas-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n     * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n     * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.pedidos.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/pedidos/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.pedidos.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/pedidos/api/PedidosControladorAutorizacionTest.java": "package com.mx.josesaid.develop.pedidos.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.pedidos.application.PedidosService;\nimport com.mx.josesaid.develop.pedidos.config.SeguridadConfig;\nimport com.mx.josesaid.develop.pedidos.infrastructure.idempotencia.Idempotencia;\nimport java.util.List;\nimport org.assertj.core.api.Assertions;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de PedidosControlador.\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n */\n@WebMvcTest(PedidosControlador.class)\n@Import({SeguridadConfig.class, PedidosControladorAutorizacionTest.Configuracion.class})\nclass PedidosControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String LINEA = \"{\\\"productoId\\\":\\\"\" + ID + \"\\\",\\\"descripcion\\\":\\\"Producto\\\",\\\"cantidad\\\":1,\\\"precioUnitario\\\":10}\";\n    private static final String COTIZACION = \"{\\\"clienteId\\\":\\\"\" + ID + \"\\\",\\\"canal\\\":\\\"WEB\\\",\\\"moneda\\\":\\\"MXN\\\",\"\n            + \"\\\"tasaIva\\\":\\\"IVA_GENERAL\\\",\\\"vigenteHasta\\\":\\\"2026-12-31\\\",\\\"lineas\\\":[\" + LINEA + \"]}\";\n    private static final String PEDIDO = \"{\\\"clienteId\\\":\\\"\" + ID + \"\\\",\\\"canal\\\":\\\"WEB\\\",\\\"moneda\\\":\\\"MXN\\\",\"\n            + \"\\\"tasaIva\\\":\\\"IVA_GENERAL\\\",\\\"lineas\\\":[\" + LINEA + \"]}\";\n    private static final String LINEAS = \"{\\\"lineas\\\":[\" + LINEA + \"]}\";\n    private static final String CANCELACION = \"{\\\"motivo\\\":\\\"ERROR_CAPTURA\\\"}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private PedidosService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(MockHttpServletRequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    private static MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder b, String cuerpo) {\n        return b.contentType(MediaType.APPLICATION_JSON).content(cuerpo);\n    }\n\n    @Test\n    void crearCotizacion() throws Exception {\n        permitido(peticion(json(post(\"/v1/cotizaciones\"), COTIZACION), \"VENTAS\"), \"POST cotizaciones\", \"VENTAS\");\n        denegado(peticion(json(post(\"/v1/cotizaciones\"), COTIZACION), \"FINANZAS\"));\n    }\n\n    @Test\n    void obtenerCotizacion() throws Exception {\n        String ruta = \"/v1/cotizaciones/\" + ID;\n        permitido(peticion(get(ruta), \"VENTAS\"), \"GET cotizacion\", \"VENTAS\");\n        permitido(peticion(get(ruta), \"FINANZAS\"), \"GET cotizacion\", \"FINANZAS\");\n        denegado(peticion(get(ruta), \"ALMACEN\"));\n    }\n\n    @Test\n    void enviarCotizacion() throws Exception {\n        String ruta = \"/v1/cotizaciones/\" + ID + \"/envio\";\n        permitido(peticion(post(ruta), \"VENTAS\"), \"POST envio\", \"VENTAS\");\n        denegado(peticion(post(ruta), \"FINANZAS\"));\n    }\n\n    @Test\n    void aceptarCotizacion() throws Exception {\n        String ruta = \"/v1/cotizaciones/\" + ID + \"/aceptacion\";\n        permitido(peticion(post(ruta), \"VENTAS\"), \"POST aceptacion\", \"VENTAS\");\n        denegado(peticion(post(ruta), \"ALMACEN\"));\n    }\n\n    @Test\n    void convertirEnPedido() throws Exception {\n        String ruta = \"/v1/cotizaciones/\" + ID + \"/pedido\";\n        permitido(peticion(post(ruta), \"DIRECCION\"), \"POST cotizacion->pedido\", \"DIRECCION\");\n        denegado(peticion(post(ruta), \"COMPRAS\"));\n    }\n\n    @Test\n    void crearPedido() throws Exception {\n        permitido(peticion(json(post(\"/v1/pedidos\"), PEDIDO), \"VENTAS\"), \"POST pedidos\", \"VENTAS\");\n        denegado(peticion(json(post(\"/v1/pedidos\"), PEDIDO), \"ALMACEN\"));\n    }\n\n    @Test\n    void buscarPedidos() throws Exception {\n        String ruta = \"/v1/pedidos\";\n        permitido(peticion(get(ruta), \"VENTAS\"), \"GET pedidos\", \"VENTAS\");\n        permitido(peticion(get(ruta), \"FINANZAS\"), \"GET pedidos\", \"FINANZAS\");\n        denegado(peticion(get(ruta), \"COMPRAS\"));\n    }\n\n    @Test\n    void obtenerPedido() throws Exception {\n        String ruta = \"/v1/pedidos/\" + ID;\n        permitido(peticion(get(ruta), \"VENTAS\"), \"GET pedido\", \"VENTAS\");\n        permitido(peticion(get(ruta), \"ALMACEN\"), \"GET pedido\", \"ALMACEN\");\n        denegado(peticion(get(ruta), \"CALIDAD\"));\n    }\n\n    @Test\n    void reemplazarLineas() throws Exception {\n        String ruta = \"/v1/pedidos/\" + ID + \"/lineas\";\n        permitido(peticion(json(put(ruta), LINEAS), \"VENTAS\"), \"PUT lineas\", \"VENTAS\");\n        denegado(peticion(json(put(ruta), LINEAS), \"ALMACEN\"));\n    }\n\n    @Test\n    void confirmarPedido() throws Exception {\n        String ruta = \"/v1/pedidos/\" + ID + \"/confirmacion\";\n        permitido(peticion(post(ruta), \"VENTAS\"), \"POST confirmacion\", \"VENTAS\");\n        denegado(peticion(post(ruta), \"ALMACEN\"));\n    }\n\n    @Test\n    void entregarPedido() throws Exception {\n        String ruta = \"/v1/pedidos/\" + ID + \"/entrega\";\n        permitido(peticion(post(ruta), \"ALMACEN\"), \"POST entrega\", \"ALMACEN\");\n        denegado(peticion(post(ruta), \"VENTAS\"));\n    }\n\n    @Test\n    void cancelarPedido() throws Exception {\n        String ruta = \"/v1/pedidos/\" + ID + \"/cancelacion\";\n        permitido(peticion(json(post(ruta), CANCELACION), \"VENTAS\"), \"POST cancelacion\", \"VENTAS\");\n        denegado(peticion(json(post(ruta), CANCELACION), \"FINANZAS\"));\n    }\n\n    @Test\n    void devolverPedido() throws Exception {\n        String ruta = \"/v1/pedidos/\" + ID + \"/devolucion\";\n        permitido(peticion(post(ruta), \"DIRECCION\"), \"POST devolucion\", \"DIRECCION\");\n        denegado(peticion(post(ruta), \"ALMACEN\"));\n    }\n\n    @Test\n    void metricasVentas() throws Exception {\n        String ruta = \"/v1/metricas/ventas?mes=2026-10\";\n        permitido(peticion(get(ruta), \"FINANZAS\"), \"GET metricas\", \"FINANZAS\");\n        permitido(peticion(get(ruta), \"DIRECCION\"), \"GET metricas\", \"DIRECCION\");\n        denegado(peticion(get(ruta), \"VENTAS\"));\n    }\n\n    @Test\n    void catalogosAutenticados() throws Exception {\n        permitido(peticion(get(\"/v1/catalogos/tasas-iva\"), \"COMPRAS\"), \"GET tasas-iva\", \"COMPRAS\");\n        permitido(peticion(get(\"/v1/catalogos/monedas\"), \"CALIDAD\"), \"GET monedas\", \"CALIDAD\");\n    }\n\n    @Test\n    void sinRolNoHayAccesoAOperaciones() throws Exception {\n        denegado(peticion(get(\"/v1/pedidos\"), \"\"));\n        denegado(peticion(get(\"/v1/metricas/ventas?mes=2026-10\"), \"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/pedidos/api/PedidosIT.java": "package com.mx.josesaid.develop.pedidos.api;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.jayway.jsonpath.JsonPath;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport com.mx.josesaid.develop.pedidos.application.ValidadorCliente;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.springframework.test.web.servlet.request.RequestPostProcessor;\nimport java.util.UUID;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\nimport static org.mockito.Mockito.doThrow;\nimport com.mx.josesaid.develop.pedidos.domain.ReglaDeNegocioException;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"pedidos.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@AutoConfigureMockMvc\n@Testcontainers\nclass PedidosIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    /** Sustituye la consulta a clientes-ms: el adaptador se prueba aparte con un servidor REST simulado. */\n    @MockitoBean\n    private ValidadorCliente validadorCliente;\n\n    private static final String CLIENTE = \"11111111-1111-1111-1111-111111111111\";\n    private static final String PRODUCTO = \"22222222-2222-2222-2222-222222222222\";\n\n    @Test\n    void flujoCompletoDeCotizacionAPedidoYDevolucion() throws Exception {\n        String cuerpo = \"\"\"\n                {\"clienteId\":\"%s\",\"canal\":\"WEB\",\"moneda\":\"MXN\",\"tasaIva\":\"IVA_GENERAL\",\n                 \"vigenteHasta\":\"2030-12-31\",\n                 \"lineas\":[{\"productoId\":\"%s\",\"descripcion\":\"Tornillo\",\"cantidad\":2,\"precioUnitario\":10.00}]}\n                \"\"\".formatted(CLIENTE, PRODUCTO);\n\n        MvcResult creada = mvc.perform(post(\"/v1/cotizaciones\").with(rol(\"VENTAS\"))\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.totales.total\").value(23.2))\n                .andReturn();\n        String cot = JsonPath.read(creada.getResponse().getContentAsString(), \"$.id\");\n\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/envio\").with(rol(\"VENTAS\")))\n                .andExpect(status().isOk());\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/aceptacion\").with(rol(\"VENTAS\")))\n                .andExpect(status().isOk());\n\n        MvcResult pedido = mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/pedido\").with(rol(\"VENTAS\")))\n                .andExpect(status().isCreated())\n                .andReturn();\n        String id = JsonPath.read(pedido.getResponse().getContentAsString(), \"$.id\");\n\n        // Una cotización solo se convierte una vez\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/pedido\").with(rol(\"VENTAS\")))\n                .andExpect(status().isConflict());\n\n        mvc.perform(post(\"/v1/pedidos/\" + id + \"/confirmacion\").with(rol(\"VENTAS\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"CONFIRMADO\"));\n        mvc.perform(post(\"/v1/pedidos/\" + id + \"/entrega\").with(rol(\"ALMACEN\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"ENTREGADO\"));\n        mvc.perform(post(\"/v1/pedidos/\" + id + \"/devolucion\").with(rol(\"VENTAS\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"CANCELADO\"))\n                .andExpect(jsonPath(\"$.motivoCancelacion\").value(\"DEVOLUCION_TOTAL\"));\n        mvc.perform(post(\"/v1/pedidos/\" + id + \"/cancelacion\").with(rol(\"VENTAS\"))\n                        .contentType(\"application/json\").content(\"{\\\"motivo\\\":\\\"ERROR_CAPTURA\\\"}\"))\n                .andExpect(status().isConflict());\n    }\n\n    @Test\n    void cotizacionVencidaResponde410YNoSeReactiva() throws Exception {\n        String cuerpo = \"\"\"\n                {\"clienteId\":\"%s\",\"canal\":\"TELEFONO\",\"moneda\":\"USD\",\"tasaIva\":\"IVA_EXENTO\",\n                 \"vigenteHasta\":\"2020-01-01\",\n                 \"lineas\":[{\"productoId\":\"%s\",\"cantidad\":1,\"precioUnitario\":50}]}\n                \"\"\".formatted(CLIENTE, PRODUCTO);\n        MvcResult creada = mvc.perform(post(\"/v1/cotizaciones\").with(rol(\"VENTAS\"))\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        String cot = JsonPath.read(creada.getResponse().getContentAsString(), \"$.id\");\n\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/envio\").with(rol(\"VENTAS\")))\n                .andExpect(status().isOk());\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/aceptacion\").with(rol(\"VENTAS\")))\n                .andExpect(status().isGone());\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/aceptacion\").with(rol(\"VENTAS\")))\n                .andExpect(status().isGone());\n        mvc.perform(get(\"/v1/cotizaciones/\" + cot).with(rol(\"VENTAS\")))\n                .andExpect(jsonPath(\"$.estatus\").value(\"VENCIDA\"));\n    }\n\n    @Test\n    void rolesYValidacionesSeAplican() throws Exception {\n        String cuerpo = \"\"\"\n                {\"clienteId\":\"%s\",\"canal\":\"WEB\",\"moneda\":\"MXN\",\"tasaIva\":\"IVA_GENERAL\",\n                 \"lineas\":[{\"productoId\":\"%s\",\"cantidad\":1,\"precioUnitario\":5}]}\n                \"\"\".formatted(CLIENTE, PRODUCTO);\n        MvcResult creado = mvc.perform(post(\"/v1/pedidos\").with(rol(\"VENTAS\"))\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        String id = JsonPath.read(creado.getResponse().getContentAsString(), \"$.id\");\n\n        // Solo ALMACEN entrega: VENTAS recibe 403\n        mvc.perform(post(\"/v1/pedidos/\" + id + \"/entrega\").with(rol(\"VENTAS\")))\n                .andExpect(status().isForbidden());\n\n        // Sin líneas no se confirma: 422\n        mvc.perform(put(\"/v1/pedidos/\" + id + \"/lineas\").with(rol(\"VENTAS\"))\n                        .contentType(\"application/json\").content(\"{\\\"lineas\\\":[]}\"))\n                .andExpect(status().isOk());\n        mvc.perform(post(\"/v1/pedidos/\" + id + \"/confirmacion\").with(rol(\"VENTAS\")))\n                .andExpect(status().isUnprocessableEntity());\n\n        // Métricas solo para DIRECCION o FINANZAS\n        mvc.perform(get(\"/v1/metricas/ventas?mes=2026-10\").with(rol(\"VENTAS\")))\n                .andExpect(status().isForbidden());\n        mvc.perform(get(\"/v1/metricas/ventas?mes=2026-10\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.mes\").value(\"2026-10\"));\n    }\n\n    private static RequestPostProcessor rol(String rol) {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n\n    @Test\n    void mismaIdempotencyKeyNoDuplicaElPedido() throws Exception {\n        String cuerpo = \"\"\"\n                {\"clienteId\":\"%s\",\"canal\":\"WEB\",\"moneda\":\"MXN\",\"tasaIva\":\"IVA_GENERAL\",\n                 \"lineas\":[{\"productoId\":\"%s\",\"descripcion\":\"Tornillo\",\"cantidad\":2,\"precioUnitario\":10.00}]}\n                \"\"\".formatted(CLIENTE, PRODUCTO);\n        String clave = \"prueba-\" + UUID.randomUUID();\n\n        MvcResult primero = mvc.perform(post(\"/v1/pedidos\").with(rol(\"VENTAS\"))\n                        .header(\"Idempotency-Key\", clave).contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        MvcResult reintento = mvc.perform(post(\"/v1/pedidos\").with(rol(\"VENTAS\"))\n                        .header(\"Idempotency-Key\", clave).contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        assertEquals((String) JsonPath.read(primero.getResponse().getContentAsString(), \"$.id\"),\n                (String) JsonPath.read(reintento.getResponse().getContentAsString(), \"$.id\"));\n\n        // Misma clave con otra petición: 422\n        mvc.perform(post(\"/v1/pedidos\").with(rol(\"VENTAS\"))\n                        .header(\"Idempotency-Key\", clave).contentType(\"application/json\")\n                        .content(cuerpo.replace(\"\\\"WEB\\\"\", \"\\\"TIENDA\\\"\")))\n                .andExpect(status().isUnprocessableEntity());\n    }\n\n    @Test\n    void clienteDesactivadoDespuesDeCotizarNoPuedeConvertirseEnPedido() throws Exception {\n        String cuerpo = \"\"\"\n                {\"clienteId\":\"%s\",\"canal\":\"WEB\",\"moneda\":\"MXN\",\"tasaIva\":\"IVA_GENERAL\",\n                 \"vigenteHasta\":\"2030-12-31\",\n                 \"lineas\":[{\"productoId\":\"%s\",\"descripcion\":\"Tuerca\",\"cantidad\":1,\"precioUnitario\":5.00}]}\n                \"\"\".formatted(CLIENTE, PRODUCTO);\n        MvcResult creada = mvc.perform(post(\"/v1/cotizaciones\").with(rol(\"VENTAS\"))\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        String cot = JsonPath.read(creada.getResponse().getContentAsString(), \"$.id\");\n\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/envio\").with(rol(\"VENTAS\")))\n                .andExpect(status().isOk());\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/aceptacion\").with(rol(\"VENTAS\")))\n                .andExpect(status().isOk());\n\n        // El cliente se desactiva después de cotizar: la conversión debe rechazarse\n        doThrow(new ReglaDeNegocioException(\"El cliente no está activo\"))\n                .when(validadorCliente).exigirActivo(UUID.fromString(CLIENTE));\n        mvc.perform(post(\"/v1/cotizaciones/\" + cot + \"/pedido\").with(rol(\"VENTAS\")))\n                .andExpect(status().isUnprocessableEntity());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/pedidos/config/RelojConfigTest.java": "package com.mx.josesaid.develop.pedidos.config;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.time.ZoneId;\nimport org.junit.jupiter.api.Test;\n\nclass RelojConfigTest {\n\n    @Test\n    void relojUsaLaZonaDeOperacion() {\n        assertEquals(ZoneId.of(\"America/Mexico_City\"), new RelojConfig().reloj().getZone());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/pedidos/domain/PedidoCotizacionTest.java": "package com.mx.josesaid.develop.pedidos.domain;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertThrows;\n\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass PedidoCotizacionTest {\n\n    private static final UUID CLIENTE = UUID.randomUUID();\n    private static final UUID PRODUCTO = UUID.randomUUID();\n\n    private static Linea linea(int cantidad, String precio) {\n        return Linea.crear(PRODUCTO, \"Tornillo\", cantidad, new BigDecimal(precio));\n    }\n\n    @Test\n    void calculaSubtotalIvaYTotalRedondeadosALaMoneda() {\n        Totales t = Totales.calcular(List.of(linea(2, \"10.00\")), \"MXN\", TasaIva.IVA_GENERAL);\n        assertEquals(new BigDecimal(\"20.00\"), t.subtotal());\n        assertEquals(new BigDecimal(\"3.20\"), t.iva());\n        assertEquals(new BigDecimal(\"23.20\"), t.total());\n    }\n\n    @Test\n    void monedaFueraDeCatalogoSeRechaza() {\n        assertThrows(ReglaDeNegocioException.class,\n                () -> Totales.calcular(List.of(linea(1, \"1\")), \"EUR\", TasaIva.IVA_GENERAL));\n    }\n\n    @Test\n    void cotizacionVencidaQuedaMarcadaYNoSeAcepta() {\n        Cotizacion c = Cotizacion.crear(CLIENTE, Canal.WEB, \"MXN\", TasaIva.IVA_GENERAL,\n                LocalDate.of(2026, 1, 1), List.of(linea(1, \"5\")));\n        c.enviar();\n        assertThrows(CotizacionVencidaException.class, () -> c.aceptar(LocalDate.of(2026, 2, 1)));\n        assertEquals(EstatusCotizacion.VENCIDA, c.getEstatus());\n    }\n\n    @Test\n    void noSeConvierteEnPedidoUnaCotizacionNoAceptada() {\n        Cotizacion c = Cotizacion.crear(CLIENTE, Canal.WEB, \"MXN\", TasaIva.IVA_GENERAL,\n                LocalDate.of(2030, 1, 1), List.of(linea(1, \"5\")));\n        c.enviar();\n        assertThrows(ConflictoException.class, () -> Pedido.desdeCotizacion(c));\n    }\n\n    @Test\n    void noSeConfirmaUnPedidoSinLineas() {\n        Pedido p = Pedido.crear(CLIENTE, Canal.TIENDA, \"USD\", TasaIva.IVA_EXENTO, List.of(linea(1, \"3\")));\n        p.reemplazarLineas(List.of());\n        assertThrows(ReglaDeNegocioException.class, () -> p.confirmar(Instant.now()));\n    }\n\n    @Test\n    void devolucionSoloDesdeEntregadoYQuedaCancelada() {\n        Pedido p = Pedido.crear(CLIENTE, Canal.WEB, \"MXN\", TasaIva.IVA_GENERAL, List.of(linea(1, \"100\")));\n        assertThrows(ConflictoException.class, p::devolver);\n        p.confirmar(Instant.now());\n        p.entregar(Instant.now());\n        p.devolver();\n        assertEquals(EstatusPedido.CANCELADO, p.getEstatus());\n        assertEquals(MotivoCancelacion.DEVOLUCION_TOTAL, p.getMotivoCancelacion());\n    }\n\n    @Test\n    void laDevolucionNoSePuedeCancelarManualmente() {\n        Pedido p = Pedido.crear(CLIENTE, Canal.WEB, \"MXN\", TasaIva.IVA_GENERAL, List.of(linea(1, \"100\")));\n        assertThrows(SolicitudInvalidaException.class, () -> p.cancelar(MotivoCancelacion.DEVOLUCION_TOTAL));\n    }\n\n    @Test\n    void unPedidoEntregadoNoSePuedeCancelar() {\n        Pedido p = Pedido.crear(CLIENTE, Canal.WEB, \"MXN\", TasaIva.IVA_GENERAL, List.of(linea(1, \"100\")));\n        p.confirmar(Instant.now());\n        p.entregar(Instant.now());\n        assertThrows(ConflictoException.class, () -> p.cancelar(MotivoCancelacion.CANCELACION_CLIENTE));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/pedidos/infrastructure/clientes/ClientesRestValidadorTest.java": "package com.mx.josesaid.develop.pedidos.infrastructure.clientes;\n\nimport static org.junit.jupiter.api.Assertions.assertDoesNotThrow;\nimport static org.junit.jupiter.api.Assertions.assertThrows;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.header;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withResourceNotFound;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withServerError;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport com.mx.josesaid.develop.pedidos.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.pedidos.domain.ServicioNoDisponibleException;\nimport java.util.UUID;\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\nimport tools.jackson.databind.ObjectMapper;\n\nclass ClientesRestValidadorTest {\n\n    private static final UUID CLIENTE = UUID.fromString(\"11111111-1111-1111-1111-111111111111\");\n    private static final String URL = \"http://clientes\";\n\n    private MockRestServiceServer servidor;\n    private ClientesRestValidador validador;\n\n    @BeforeEach\n    void preparar() {\n        RestClient.Builder builder = RestClient.builder();\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        validador = new ClientesRestValidador(builder, URL, new ObjectMapper());\n        SecurityContextHolder.getContext().setAuthentication(new JwtAuthenticationToken(\n                Jwt.withTokenValue(\"tok\").header(\"alg\", \"RS256\").claim(\"sub\", \"usuario\").build()));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    @Test\n    void clienteActivoPasaYReenviaElToken() {\n        servidor.expect(requestTo(URL + \"/v1/clientes/\" + CLIENTE))\n                .andExpect(header(\"Authorization\", \"Bearer tok\"))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + CLIENTE + \"\\\",\\\"estatus\\\":\\\"ACTIVO\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertDoesNotThrow(() -> validador.exigirActivo(CLIENTE));\n        servidor.verify();\n    }\n\n    @Test\n    void clienteSuspendidoRechaza() {\n        servidor.expect(requestTo(URL + \"/v1/clientes/\" + CLIENTE))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + CLIENTE + \"\\\",\\\"estatus\\\":\\\"SUSPENDIDO\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertThrows(ReglaDeNegocioException.class, () -> validador.exigirActivo(CLIENTE));\n    }\n\n    @Test\n    void clienteInexistenteRechaza() {\n        servidor.expect(requestTo(URL + \"/v1/clientes/\" + CLIENTE)).andRespond(withResourceNotFound());\n\n        assertThrows(ReglaDeNegocioException.class, () -> validador.exigirActivo(CLIENTE));\n    }\n\n    @Test\n    void clientesCaidoDaServicioNoDisponible() {\n        servidor.expect(requestTo(URL + \"/v1/clientes/\" + CLIENTE)).andRespond(withServerError());\n\n        assertThrows(ServicioNoDisponibleException.class, () -> validador.exigirActivo(CLIENTE));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/pedidos/infrastructure/idempotencia/RegistroIdempotenciaIT.java": "package com.mx.josesaid.develop.pedidos.infrastructure.idempotencia;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport org.flywaydb.core.Flyway;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.datasource.DriverManagerDataSource;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Reserva de Idempotency-Key contra PostgreSQL real (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@Testcontainers\nclass RegistroIdempotenciaIT {\n\n    @Container\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    private static final Instant T0 = Instant.parse(\"2026-11-05T12:00:00Z\");\n\n    private JdbcTemplate jdbc;\n\n    @BeforeEach\n    void migrarBaseLimpia() {\n        DriverManagerDataSource ds = new DriverManagerDataSource(\n                postgres.getJdbcUrl(), postgres.getUsername(), postgres.getPassword());\n        Flyway flyway = Flyway.configure().dataSource(ds).cleanDisabled(false).load();\n        flyway.clean();\n        flyway.migrate();\n        jdbc = new JdbcTemplate(ds);\n    }\n\n    private RegistroIdempotencia registroEn(Instant instante) {\n        return new RegistroIdempotencia(jdbc, Clock.fixed(instante, ZoneOffset.UTC));\n    }\n\n    @Test\n    void reservaFrescaNoSeRetoma() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertFalse(registroEn(T0.plusSeconds(60)).reservar(\"k1\", \"h1\"));\n    }\n\n    @Test\n    void reservaSinCompletarSeRetomaTrasLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h2\"));\n        assertEquals(\"h2\", registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().huella());\n        assertFalse(registroEn(T0.plusSeconds(200)).reservar(\"k1\", \"h2\"));\n    }\n\n    @Test\n    void respuestaCompletadaNoSeRetomaAunquePaseLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        registroEn(T0).completar(\"k1\", 201, \"{}\");\n        assertFalse(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().completada());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/pedidos/infrastructure/indicadores/PublicadorIndicadoresVentasIT.java": "package com.mx.josesaid.develop.pedidos.infrastructure.indicadores;\n\nimport com.mx.josesaid.develop.pedidos.application.ValidadorCliente;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.math.BigDecimal;\nimport java.time.Duration;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"pedidos.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@Testcontainers\nclass PublicadorIndicadoresVentasIT {\n\n    @MockitoBean\n    ValidadorCliente validadorCliente;\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresVentas publicador;\n\n    private static final String PRODUCTO = \"22222222-2222-2222-2222-222222222222\";\n\n    @Test\n    void ventasDelMesIncluyenIvaSoloConfirmadosYEntregadosEnMxn() {\n        String periodo = YearMonth.now(ZoneId.of(\"America/Mexico_City\")).toString();\n        pedido(\"CONFIRMADO\", \"IVA_GENERAL\", \"MXN\", 2, \"10.00\");    // 23.20\n        pedido(\"ENTREGADO\", \"IVA_FRONTERIZO\", \"MXN\", 1, \"10.00\");  // 10.80\n        pedido(\"BORRADOR\", \"IVA_GENERAL\", \"MXN\", 1, \"100.00\");     // excluido: borrador\n        pedido(\"CANCELADO\", \"IVA_GENERAL\", \"MXN\", 1, \"100.00\");    // excluido: cancelado\n        pedido(\"CONFIRMADO\", \"IVA_GENERAL\", \"USD\", 1, \"100.00\");   // excluido: no es MXN\n\n        publicador.publicarPeriodo(periodo);\n\n        String clave = PublicadorIndicadoresVentas.AREA + \"|\" + PublicadorIndicadoresVentas.NOMBRE + \"|\" + periodo;\n        String payload = leerIndicador(clave);\n        assertEquals(\"VENTAS_ATENCION_CLIENTES\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(34.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private void pedido(String estatus, String tasa, String moneda, int cantidad, String precio) {\n        UUID id = UUID.randomUUID();\n        jdbc.update(\"\"\"\n                INSERT INTO pedidos (id, cliente_id, canal, moneda, tasa, estatus, fecha_confirmacion, version)\n                VALUES (?, ?, 'WEB', ?, ?, ?, now(), 0)\n                \"\"\", id, UUID.randomUUID(), moneda, tasa, estatus);\n        jdbc.update(\"\"\"\n                INSERT INTO lineas_pedido (pedido_id, posicion, producto_id, descripcion, cantidad, precio_unitario)\n                VALUES (?, 1, ?, 'Tornillo', ?, ?)\n                \"\"\", id, UUID.fromString(PRODUCTO), cantidad, new BigDecimal(precio));\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n"};
